programs.sol:
"""Token-boundary-sensitive detector for the lie/li character family.

Large negative responses occur on 烈/裂 (lie), beautiful 丽/麗 (li),
and leap 跃/躍. Compound tokens dilute these responses. A few related
phonetic continuations (l + iet, Vietnamese liệt) also respond. This is a
partial account. Document starts have additional script/case biases and
negative responses to import/declaration keywords and comment openers.
The document-initial decimal prefix 12 also gives a negative response.
Most remaining activations are left at zero; double middle-dot punctuation
has its own negative response.
"""
from functools import lru_cache
import regex
from pypinyin import lazy_pinyin
import cedict

READS = ()

@lru_cache(maxsize=8192)
def token_response(s):
    if s == '··':
        return -2.08
    if s.strip().lower() == 'liệt':
        return -3.8
    if s.strip().lower() == 'lie':
        return -0.6 if 'L' in s else -0.3
    if not regex.fullmatch(r'\p{Script=Han}+', s):
        return 0.0
    n = len(s)
    if s.endswith(('烈', '裂')):
        return -5.3 if n == 1 else -3.1
    if '烈' in s or '裂' in s:
        return -1.5 if s.endswith('的') else -0.7
    if s.endswith(('丽', '麗')):
        return -2.9 if n == 1 else -1.0
    if s.endswith(('跃', '躍')):
        if n == 1:
            return -4.5
        return -3.2 if s.startswith('活') else -1.1
    if n == 1 and lazy_pinyin(s) == ['lie']:
        return -1.8 if s in ('猎', '獵', '冽') else -0.5
    if s == '利':
        return -0.65
    # Dictionary-based, weaker responses to nimbleness and fluency.
    senses = ' '.join(cedict.glosses(s)).lower()
    if regex.search(r'\b(fluent|agile|nimble)\b', senses):
        return -0.6
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    same_doc = (prefix.position > 0 and
                prefix.document_ids[-1] == prefix.document_ids[-2])
    previous = prefix.token_strings[-2] if same_doc else ''
    value = token_response(s)
    if not same_doc:
        # Document-initial source-code headers are a separate response.
        if s in {'import', 'from', 'using', 'namespace'}:
            value = -0.75
        elif s in {'const', 'var'}:
            value = -1.72
        elif s in {'let', 'function'}:
            value = -1.0
        elif s.startswith('//') and '\n' in s:
            value = -2.85
        elif s.startswith(('/*', '<?')):
            value = -0.8
        elif s == '<|im_start|>':
            value = -0.205
        elif s.isspace():
            value = -0.2
        elif value == 0.0:
            if regex.search(r'\p{Script=Han}', s):
                value = 0.25
            elif s.strip()[:1].isupper():
                value = -0.12
            elif s.strip()[:1].islower():
                value = -0.04
    if s == '2' and previous == '1':
        previous_is_first = (prefix.position == 1 or
                             prefix.document_ids[-3] != prefix.document_ids[-2])
        if same_doc and previous_is_first:
            value = -3.11
    if s == '烈' and previous.endswith(('强', '強', '熱')):
        value = -7.3
    if s == '利' and previous.endswith('犀'):
        value = -3.4
    if s == 'iet':
        if previous.lower().endswith('l'):
            value = -3.8
        elif previous.endswith(('św', 'świ')):
            value = -2.8
        elif previous.lower().endswith('r'):
            value = -0.8
    if s == 'ie' and previous.lower().endswith('l'):
        value = -0.5
    return None, value

"""A sparse detector of opening titles and question syntax.

The largest negative pulses are opening `Title:` labels and Markdown
questions (especially `How to` and `How can I`). A `Q:` opening gives a
short, decaying negative response, stronger on English grammatical and
programming words. Local `how to`, `not set`, and C++/C# syntax give smaller
negative pulses. Other tokens are zero except for coarse start offsets.
This approximates the strong patterns, not the weak lexical variation.
"""
READS = ()

ARTICLES = set('a an the'.split())
AUXILIARIES = set((
    'am is are was were be been being do does did have has had '
    'can could may might must will would shall should'
).split())
PREPOSITIONS = set((
    'in on at to of from for with by as into over under after before '
    'between through without inside outside within about against'
).split())
PRONOUNS = set('i me my we us our you your he she it they them'.split())
CODE_WORDS = set((
    'code function variable array string list loop call file print input '
    'output type value return data index table query class method object '
    'parameter command script process thread instance component pointer '
    'format program syntax compiler'
).split())
QUESTION_STARTS = {
    'how': 2.94, 'why': 3.11, 'what': 2.40, 'which': 1.75,
    'where': 1.24, 'when': 0.98, 'who': 0.92, 'can': 3.65,
}
QUESTION_AUXILIARIES = set(
    'am is are was were do does did could would should will'.split()
)
HOW_CONTINUATIONS = {
    'to': 4.38, 'can': 3.92, 'do': 3.68, 'does': 3.31,
    'could': 2.67, 'would': 1.83, 'should': 2.13,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    word = token.strip().lower()
    english = word.isascii() and word.isalpha()
    if carry is None or carry[0] != doc:
        pos, opening, previous = 0, [], ''
    else:
        _, pos, opening, previous = carry
    if pos < 4:
        opening = opening + [token]
    value = 0.0

    if pos == 0:
        value = 0.16
        if english:
            value = 0.23 + 0.08 * token.strip()[0].isupper()
            value -= 0.14 * (word in AUXILIARIES)
            value -= 0.10 * (word in PREPOSITIONS)
            value -= 0.09 * (word in CODE_WORDS)
        if word in ARTICLES:
            value = 0.0
        if token.isspace() or word.isdigit():
            value = 0.04
        if token in ('We', 'They'):
            value = 0.82
        elif token in ('He', 'She'):
            value = 0.61
        if token == 'Title':
            value = 0.46
        elif token == 'Q':
            value = 0.66
        elif token == '//':
            value = -1.24
        elif token == '#':
            value = -0.196
        elif token == '##':
            value = 0.326
        elif token == '###':
            value = 0.04
        elif token == '<|im_start|>':
            value = 0.32
    elif pos == 1 and opening[0] == 'Title' and token == ':':
        value = -5.72
    elif (opening[0] == 'Q' and pos < 32
          and len(opening) > 1 and opening[1].startswith(':')):
        if pos == 1:
            value = -0.21
        else:
            value = (-0.13 - 0.42 * english
                     - 0.95 * (word in PREPOSITIONS)
                     - 0.31 * (word in AUXILIARIES)
                     - 0.36 * (word in CODE_WORDS)) * 0.85 ** (pos - 2)
            if pos == 2 and word == 'how':
                value = -1.15
            elif pos == 3 and previous == 'how' and word == 'to':
                value = -1.8
    elif opening[0] in ('#', '##', '###') and pos < 16:
        scale = 0.55 ** (len(opening[0]) - 1)
        value = (0.12 - 0.29 * english
                 - 1.09 * (word in AUXILIARIES)
                 - 1.06 * (word in CODE_WORDS)
                 - 0.40 * (word in PRONOUNS)) * 0.65 ** (pos - 1)
        if pos == 1 and (word in QUESTION_STARTS or word in QUESTION_AUXILIARIES):
            value = -QUESTION_STARTS.get(word, 2.3)
            if token.strip().islower():
                value *= 0.6
        elif pos == 2 and opening[1].strip().lower() == 'how':
            value = -HOW_CONTINUATIONS.get(word, 0.6)
        elif pos == 3 and opening[1].strip().lower() == 'how':
            if previous == 'to' and english:
                value = -0.9
            elif previous == 'can' and word == 'i':
                value = -4.92
            elif previous == 'do' and word == 'you':
                value = -1.35
        value *= scale
    if pos > 3 or (pos > 0 and opening[0] not in ('Q', '#', '##', '###')):
        if previous == 'how' and word == 'to':
            value -= 0.09
        elif previous == 'not' and word == 'set':
            value -= 0.32
        elif previous == 'c' and token in ('++', '#'):
            value -= 0.44

    return (doc, pos + 1, opening, word), float(value)

programs.haiku:
"""Layer 1, MLP down-projection, component 5762: a word-ending detector.

What it responds to, in plain terms. It reads the word a token completes (pieces joined
until a space, newline or punctuation starts a new word). Three things move it:

1. The body part "shoulder" (also "shoulders", "shouldered"): strongly negative, -8.
2. A "-er" or "-ers" ending on a sport, activity, trade or group stem, so that the word is a
   person noun: football|er, garden|er, labour|er, camp|er, surf|er, young|er: positive, +2.
   Its real values are larger for the rarest ones (footballer about +5), so +2 is a
   conservative guess that does best across the group.
3. A "-er" ending on a stem that is a sound or motion verb, or a plain object rather than a
   person (whisp|er, flick|er, whisk|er, feath|er, butt|er, skyscrap|er): negative, -2.

Every other token is predicted as 0. The component is near zero on most tokens.
"""
READS = ()

# Sports, activities, trades and groups whose -er form names a person.
PERSON_STEMS = {
    "football", "soccer", "golf", "cricket", "rugby", "surf", "ski", "swim", "row", "hurl",
    "outfield", "midfield", "lineback", "garden", "labor", "labour", "camp", "farm", "ranch",
    "dream", "wander", "trooper", "troop", "overse", "hairdress", "cowork", "treasur",
    "messeng", "young", "short", "teen", "school", "preschool", "homeschool", "highland",
    "western", "feder", "sin", "kick",
}

# Sound or motion verbs, and plain things, that happen to end in -er.
NON_PERSON_STEMS = {
    "whisp", "whisk", "flick", "shudd", "shiv", "wither", "smother", "sputt", "mutt", "thund",
    "shimm", "flutt", "stutt", "chatt", "shatt", "sequest", "skyscrap", "millilit", "joint",
    "sketch", "spott",
}


def _word(carry, prefix):
    """The word being built, in lowercase. A piece of letters with no space before it
    continues the word; anything else, or the first token of a document, starts a new one."""
    new_doc = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    piece = prefix.token_strings[-1]
    if new_doc or carry is None or not piece.isalpha():
        return piece.strip().lower()
    return carry + piece.lower()


def step(carry, prefix, upstream):
    word = _word(carry, prefix)
    if word.startswith("shoulder"):
        return word, -8.0
    if word.endswith("ers"):
        stem = word[:-3]
    elif word.endswith("er"):
        stem = word[:-2]
    else:
        return word, 0.0
    if stem in PERSON_STEMS:
        return word, 2.0
    if stem in NON_PERSON_STEMS:
        return word, -2.0
    return word, 0.0

programs.sol:
"""A quotation-boundary approximation.

Left-curly quotes, guillemets and CJK quotation brackets give positive
pulses. Straight quotes get a larger pulse in prose than beside code/data
syntax. Quote balance and spacing determine weak or negative closing-mark
pulses, with stronger negatives for some unpaired marks after whitespace.
Quote balance resets at document changes.
There are also small backtick responses, a negative @return response, and
a small negative baseline at the beginning of a document. This deliberately
leaves most ordinary-token variation unexplained.
"""

READS = ()
OPENERS = '“‘«「『《'
PAIRS = {'”': '“', '’': '‘', '»': '«', '」': '「',
         '』': '『', '》': '《'}
QUOTES = set(OPENERS + ''.join(PAIRS) + '\"\'„')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', {}, {}, 0)
    _, recent, last_open, last_seen, pos = carry
    token = prefix.token_strings[-1]
    text = token.lstrip()
    leading_space = token[:1].isspace()
    prev = recent[-1:]
    prev_nonspace = recent.rstrip()[-1:]
    code = any(c in recent[-160:] for c in '{}=')
    key_or_list = recent.rstrip().endswith(('\":', '\",', "':", "',"))
    value = -0.195 if pos == 0 else 0.0

    if text == 'return' and prev_nonspace in ('@', '\\'):
        value = -2.15
    elif text.startswith(('“', '‘', '«', '「', '『', '《')):
        q = text[0]
        value = {'“': 1.27, '‘': 1.15, '«': 0.97,
                 '「': 0.96, '『': 0.59, '《': 0.53}[q]
        if len(text) > 1:
            value *= 0.67
        if q == '“' and pos - last_open.get('„', -10000) < 60:
            value = 0.25
    elif text in PAIRS:
        q = text
        distance = pos - last_open.get(PAIRS[q], -10000)
        spaced = leading_space or prev.isspace()
        if q == '’':
            value = -1.3 if spaced else 0.18
        elif distance > 9000:
            value = -4.4 if spaced else -0.75
            if pos < 5:
                value = -2.5
        elif q == '”' and spaced:
            value = -1.5
        elif spaced:
            value = -min(2.0, 0.02 * distance)
        elif distance <= 20:
            value = 0.12
        else:
            value = -0.2
        if spaced and pos - last_seen.get(q, -10000) <= 4:
            value *= 0.4
    elif token == '\\"' and prev in ('[', '{', '('):
        value = -0.82
    elif text in ('"', "'"):
        if leading_space:
            if prev_nonspace == ':':
                value = -0.1 if code or key_or_list else 1.05
            elif code or key_or_list or prev_nonspace in ('[', '{', '='):
                value = 0.12
            elif prev_nonspace == ',':
                value = 1.0 if text == '"' else 0.7
            elif prev.isspace():
                value = 0.65 if '\n' in recent[-2:] else 0.12
            else:
                value = 0.85 if text == '"' else 0.55
        elif prev.isspace() and not code:
            value = 0.8
        else:
            value = -0.05 if text == '"' else -0.09
    elif len(text) > 1 and text[0] == '"' and text[1].isalnum():
        value = 0.5
    elif text.endswith('“'):
        value = 0.9
    elif text.endswith('「'):
        value = 0.68
    elif text in (',"', '."', ",'"):
        value = -0.19
    elif text.endswith('”'):
        value = -0.35 if any(c in text for c in '。！？') else 0.05
    elif text in ('`', '``'):
        value = (0.13 if len(text) == 1 else 0.26) if leading_space else 0.0

    for q in token:
        if q in OPENERS + '„':
            last_open[q] = pos
        elif q in PAIRS:
            last_open.pop(PAIRS[q], None)
        if q in QUOTES:
            last_seen[q] = pos
    return (doc, (recent + token)[-200:], last_open, last_seen, pos + 1), value

"""Approximate a negative spelling response to short 'em' fragments.

Fold case, accents and selected Greek/Cyrillic letter equivalents. Short
fragments and e-to-m token joins get stronger negative values than long
tokens. Isolated -ema, -emia and -emic endings are especially strong.
A negative response fades onto unspaced alphabetic continuations; each new
document instead starts with a small positive bias. These rules capture the
broad spelling trigger, not all of its lexical and contextual variation.
"""
import unicodedata
from functools import lru_cache

READS = ()
E_AND_M = str.maketrans({'е': 'e', 'э': 'e', 'ε': 'e', 'η': 'e',
                        'м': 'm', 'μ': 'm'})


@lru_cache(maxsize=8192)
def spelling(text):
    text = unicodedata.normalize('NFD', text.casefold())
    plain = ''.join(c for c in text if not unicodedata.combining(c))
    return plain.translate(E_AND_M)


def response(raw, text, previous):
    word = text.strip()
    n = len(word)
    if text.startswith('m') and previous.endswith('e'):
        if n <= 2:
            return -4.8 if 'μ' in raw.casefold() else -3.0
        return -1.3 if n == 3 else -0.5 if n == 4 else -0.1
    em = word.find('em')
    if em < 0:
        return 0.0
    if word.endswith(('emia', 'emic')):
        return -5.2 if n == 4 else -0.3
    if word == 'ema':
        return -4.3
    if n <= 3:
        if text[:1].isspace():
            return -0.65 if word.endswith('em') else -0.26
        return -1.4 if previous[-1:].isalpha() else -0.4
    if n == 4:
        if em == 0:
            return -1.3
        return -0.05 if text[:1].isspace() else -0.36
    if em <= 1:
        return -0.23 if n - em - 2 <= 2 else -0.08
    return -0.09 if n == 5 else -0.03


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, '', 0.0)
    _, previous, old = carry
    raw = prefix.token_strings[-1]
    text = spelling(raw)
    value = response(raw, text, previous)
    if text[:1].isalpha():
        value += 0.2 * min(old, 0.0)
    if first:
        value += 0.25 if any(c.isalpha() for c in raw) else 0.16
    return (doc, text, value), float(value)

programs.haiku:
"""Draft H: em-fragments with two strengths; medical stems strongest; piece after a fragment."""
READS = ()

# Strongest: the -emia / -emic / -ema endings of medical words (hyperglycemia, ischemic, edema).
STRONG = {"emia", "emic", "ema", "emias", "emics", "emie", "olem"}
# Medium: other fragments spelling 'em' inside a word (Latin/Cyrillic), e.g. 'ém' in épidémie.
MEDIUM = {"ém", "ème", "èmes", "ême", "emi", "eme", "emes", "emat", "dem", "MI", "EM"}
# Weak: bare 'em' / 'ем' and similar.
WEAK = {"em", "ем", "êm", "èm", "emo", "emy", "eman", "sem", "rem", "lem", "hem", "μ"}
# A piece that follows a fragment and completes -emia / -emic / -emie (hypo-natr-emia, is-chem-ic).
ENDINGS = {"ia", "ic", "ie", "ica", "ical", "ias", "i", "I", "ics"}

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    after_fragment = carry is True and not new_doc
    piece = s.strip()
    spaced = s[:1].isspace()
    if piece in STRONG:
        value = -5.0
    elif piece in MEDIUM:
        value = -0.8 if spaced else -2.5
    elif piece in WEAK and not (spaced and piece == "μ"):
        value = -0.6 if spaced else -1.3
    elif after_fragment and piece in ENDINGS:
        value = -4.0
    else:
        value = 0.0
    is_fragment = piece in STRONG or piece in MEDIUM or piece in WEAK
    return is_fragment, value

programs.sol:
"""Approximate sparse responses to document-conversion scaffolding.

Reference attributes, empty formatting spans, rules, citation and download
phrases mostly give negative pulses. Some equation, cross-link, supplementary
material and patent-claim boundaries give positive pulses. A few leading
formatting characters, type words and the opening number 12 are also handled.
Pulse heights are approximate; unrecognized text gets zero. State is only
160 characters of preceding text, reset when the document label changes.
"""
import re

READS = ()


def response(token, tail, first):
    # Distinctive document openings and repeated leaders.
    start = tail.rsplit('<|endoftext|>', 1)[-1]
    if token == '2' and start in ('1', '12'):
        return -7.57 if start == '1' else -3.04
    if token == '··' and (not start or tail.endswith('·')):
        return -4.16
    if token == '^^^^' and not start.strip('^'):
        return -4.87
    if first or not start:
        if token in ('int', 'void', 'string', 'char'):
            return -2.7
        if token in ('\\n', '\\t'):
            return -2.55
        if token == '\t':
            return -1.82
        if token == '\xa0':
            return -2.12
        if token == ' .':
            return -3.14
        if token == '\\"':
            return -3.37
        if token.isspace():
            return -0.5
    # Scientific conversion markup, equations and rules.
    if token == ':' and start == '---\nabstract':
        return -10.0
    if token == '-type' and tail.endswith('{ref'):
        return -7.54
    if token == '-label' and tail.endswith('{data'):
        return -3.0
    if token.startswith('"}') and '{ref-type="' in tail:
        attribute = tail.rsplit('{ref-type="', 1)[-1]
        if '"' not in attribute:
            if attribute == 'table-fn':
                return -0.9
            return -2.6 if attribute == 'ref' else -1.9
    if token.startswith('{}') and tail.endswith(']'):
        if token == '{}':
            return -5.5 if tail.endswith('\\]]') else -8.5
        return -5.8 if token.endswith('.') else -4.5
    if (token in ('},', '}\n\n') and tail.endswith(']{')
            and not tail.endswith('[]{')):
        return -4.0
    if token == '](' and '{data-label=' in tail and tail.endswith('\"}'):
        return 2.0
    if token == '}' and tail.endswith(r'\end{aligned'):
        return 1.9
    if token == '$$' and tail.endswith(r'\end{aligned}'):
        return -3.25
    if token == '#' and tail.endswith(']('):
        return -1.05
    if token == '__':
        rule = re.search(r'_{36,}$', tail)
        if rule:
            return -max(0.6, 8.0 - 0.075 * len(rule[0]))
    if token.strip() in ('_', '__') and tail.endswith('>`'):
        return -5.8 if token.strip() == '_' else -3.9
    # Citation and publisher/preview boilerplate.
    patent_labels = ('Pat.', 'Patent', 'Patent Application', 'Patent Publication')
    if token == ' No' and tail.endswith(patent_labels):
        return -1.65
    if token.lower() == ' claim' and tail.endswith(('Regarding', 'As per')):
        return -2.05
    if token == ' claims' and (tail.endswith('appended') or
            tail.endswith('following') and 'invention' in tail):
        return 1.8
    if token == ' Scholar' and tail.endswith('Google'):
        return -6.5 if tail.endswith(('PubMedGoogle', 'ArticleGoogle')) else -1.35
    if token == ' file' and tail.endswith('Click here for additional data'):
        return -4.5
    if (token.lower() in (' material', ' materials')
            and tail.lower().endswith('supplementary')):
        return 2.0
    if token in (' page', ' pages') and tail.endswith('This preview shows'):
        return -2.8
    if token == ' Document' and tail.endswith('View Full'):
        return -3.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = response(token, tail, first)
    return (doc, (tail + token)[-160:]), value

"""Approximate a spelling-sensitive rang/range feature, not a semantic range test.

Large observed activations cluster on range-like spellings.  Give positive
levels to that family and several code forms; strengthen ``in range`` and
weaken ``wide/broad/diverse/full range``.  Orange and ranch are positive,
bang negative.  Split ang/anch/anj continuations are usually positive after
r and negative after b/v/w/d, with weaker rearrange and spr- continuations.

Keep just 32 recent characters to recover the current word's ending, resetting
at document boundaries.  Unmatched cases predict zero; many smaller and
non-Latin activations are deliberately left unexplained.
"""
import re

READS = ()

RANGE_FORMS = re.compile(r'rang(?:e[ds]?|ing|ers?)?')
NASAL_FRAGMENTS = re.compile(
    r'(?:ang(?:e(?:[drs]|ment)?|ing|[aio]n?)?|anch|anj|äng)'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    match = re.search(r'[a-zA-Z]+$', tail)
    previous = match[0] if match else ''
    token = prefix.token_strings[-1]
