PERSON = {'i', 'you', 'we', 'they', 'he', 'she'}
REFER = {'refer', 'refers', 'referred', 'referring'}
BE = {'am', 'is', 'are', 'was', 'were', "'m", "'re", "'s", '’m', '’re', '’s'}
UNITS = (r'(?:kmh|[numcdkµ]?m|ft|yd|mi|in|ms|sec|min|hr|s|h|kg|mg|g|'
         r'ml|mL|mol|d|L|K|Hz|Å)')
UNIT_END = re.compile(r'(?<![a-zA-Z\\])(' + UNITS + r')[ \t]*$')
POWER = re.compile(r'[ \t]*(?:\([ \t]*(?=[-−–À]))?(?:\^[ \t]*)?(?:[-−–À][ \t]*)?$')


def measurement(tail, word):
    """Powers next to a unit: distinguish unit symbols from algebraic variables."""
    if not tail or tail[-1] in '\n\r':
        return 0.0
    clean = re.sub(r'\\(?:mathrm|text|rm)', '', tail)
    clean = clean.translate(str.maketrans('', '', '${}'))
    inverse = bool(re.search(r'[-−–À][ \t]*$', clean))
    explicit = inverse or clean.rstrip().endswith('^')
    explicit |= word in {'²', '³', '^', '-', '−', '–', '^-', '^{-'}
    if word == '1' and not inverse:
        return 0.0
    if word in {'1', '2', '3'}:
        clean = POWER.sub('', clean)
    match = UNIT_END.search(clean)
    if not match:
        return 0.0
    unit = match[1]
    before = clean[:match.start(1)]
    slash = before.rstrip().endswith('/')
    quantity = bool(re.search(
        r'(?<![A-Za-z0-9])(?:\d+(?:[.,]\d+)*|'
        r'hundred|thousand|million|billion)[ \t]+$', before))
    physics = bool(re.search(
        r'\b(?:cm|mm|km|mol|kg|mg|lb|oz|Pa|Btu|Hz)\b|m/s|(?<![A-Za-z])[NWSJ][.· ]',
        clean[-70:]))
    if unit == 'in':
        if slash and word in {'²', '³'}:
            return 5.0
        return 2.5 if quantity and not tail.endswith(' ') else 0.0
    if unit == 'ms' and re.search(r'\d[ \t]*$', before) and explicit:
        return 8.0
    if unit == 'K' and not re.search(r'\b(?:cm|mm|mol|kg|mg|m)\b', before[-30:]):
        return 0.0
    if unit in {'m', 's', 'h', 'K', 'L', 'g', 'd'}:
        if unit in {'K', 'L', 'g', 'd'} and not inverse:
            return 0.0
        if unit == 'm' and slash:
            return 8.0
        if unit == 'h' and not explicit:
            return 0.0
        if physics:
            return 8.0
        if quantity:
            return 5.0
        return 1.0 if unit == 'm' else 0.0
    if unit in {'mg', 'kg', 'ml', 'mL', 'mol', 'sec', 'min', 'hr'}:
        return 8.0 if explicit else 0.0
    if unit in {'ft', 'mi', 'ms'} and not (
            quantity or physics or (unit == 'ft' and slash)):
        return 0.5
    if unit == 'km':
        return 9.0
    if word == '³' and unit == 'cm' and slash:
        return 5.6
    return 7.0 if slash else 6.5


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = previous.strip().lower()
    value = 0.0
    what = bool(re.search(r'\bwhat\b', tail[-65:], re.I))
    if word in {'mean', 'means', 'meant', 'meaning'}:
        value = {'mean': -1.6, 'means': -0.7,
                 'meant': -3.0, 'meaning': -0.7}[word]
        if word == 'mean':
            if prev in PERSON or re.search(r'\b[“\"]?I$', tail):
                value = -9.0 if prev == 'you' else -7.5
                if re.search(r'\bby\b', tail[-75:], re.I):
                    value = -12.0
            elif prev in {'a', 'the', 'of', 'with', 'and', 'standard'}:
                value = 0.0
            elif prev == 'shall':
                value = -5.4
            elif prev in {'could', 'must', 'may', 'can', 'to'}:
                value = -3.0
            elif prev == 'might':
                value = -4.5
            elif prev in {"'t", '’t', 'not', 'just', 'really', 'often'}:
                value = -3.0
                if re.search(r'\b(?:I|you|we)\b', tail[-35:], re.I):
                    value = -7.0
            elif prev == 'it':
                value = -2.6
        elif word == 'means':
            if prev in PERSON:
                value = -6.5
            elif prev == 'it':
                value = -2.7
            elif prev in {'this', 'that'}:
                value = -0.3 if previous.strip()[0].isupper() else -1.5
            elif prev == 'which':
                value = -0.45
            elif prev in {'just', 'probably', 'usually', 'likely', 'actually'}:
                value = -4.0
            elif previous.rstrip().endswith(('"', '”')):
                value = -4.8
            elif re.search(r'\bterm\b', tail[-75:], re.I):
                value = -3.4
        elif word == 'meant':
            if prev in PERSON:
                value = -8.0 if prev in {'i', 'you'} else -6.5
            elif prev == 'are':
                value = -1.7
            elif prev == 'problem':
                value = -4.6
            elif prev == 'is':
                value = -6.0 if re.search(r'\bby\b', tail[-75:], re.I) else -3.5
        elif previous.rstrip().endswith(('"', '”')):
            value = -3.0
    elif word in REFER:
        value = -0.5
        if word == 'referring':
            value = -3.5 if prev in BE else -0.8
    elif word == 'to' and prev in REFER:
        value = -1.7 if prev == 'referring' else -0.65
    elif word == 'about':
        if prev == 'talking':
            value = -5.5 if what else -3.0
        elif prev in {'talk', 'talks', 'talked', 'spoke', 'speaking'}:
            value = -0.65
    elif word == 'talking' and (prev in BE or prev == 'not'):
        value = -2.2 if prev in {'am', "'m", "'re", '’m', '’re'} else -1.4
    elif word == 'saying' and (prev in BE or prev == 'not'):
        value = -1.7 if prev in {'am', "'m", 'not'} else -0.8
    elif word == 'asking' and prev in BE | {'just'}:
        value = -0.8
    elif word in {'1', '2', '3', '²', '³'}:
        value = measurement(tail, word)
        if value == 0.0 and word == '1':
            if ('^' in previous and '-' in previous) or re.search(
                    r'(?:sin|cos|tan)[−-]$', tail):
                value = 3.0
            elif prev in {'-', '−', '–', '(-', '{-'}:
                value = 0.6 if re.search(r'[A-Za-zθ][ \t]*[-−–]$', tail) else 0.1
    elif word in {'^', '-', '−', '–', '^-', '^{-', '(-'}:
        value = 0.65 * measurement(tail, word)
    elif word == '¹':
        value = 0.8
    elif token in {')', ']', '）'}:
        # Closing a parenthesized length or speed, not a free variable.
        unit = UNIT_END.search(tail)
        if unit and (unit[1] in {'km', 'cm', 'mm', 'ft', 'yd', 'mi', 'Å'} or
                     re.search(r'\d[ \t]*' + UNITS + r'$', tail)):
            value = 0.65
    return (doc, (tail + token)[-120:], token), value

programs.haiku:
READS = ()
"""Exponents of physical units, and the verb 'mean'.

Positive: the power of a unit of measure. When a unit is followed by its exponent (cm³, m/s²,
cm 2, kg·m⁻¹, mol L-1, cm$^{-2}$, sin⁻¹), the exponent token fires: strongly after a long unit
(cm, kg, ms, mol, ft, or a slash unit like /m), less after a single letter (m, s, g, L).
Negative: the verb 'mean' meaning 'to signify / to intend' ("I mean", "you mean", "it means"),
plus "talking about" and "referring to". The noun or statistic 'mean' ("the mean") is about 0.
Everything else is 0."""

LONG_UNITS = {"cm", "mm", "km", "ft", "yd", "mi", "kg", "mg", "ml", "ms", "min", "sec", "kmh", "mph",
              "lb", "oz", "hr", "kW", "MW", "Pa", "Hz", "eV", "erg", "mol", "dwt", "gal", "acre"}
SHORT_UNITS = {"m", "s", "g", "h", "L", "K", "N", "W", "J", "V", "A", "l"}
POWER_SIGNS = {"−", "À", "–", "^", "^{-", "$^{-", "^-", "(-", "$"}
CARETS = {"^", "−", "^{-", "$^{-", "$"}
MARKUP = {"$", "{", "}", "\\mathrm", "\\text", ""}
INVERSE_FUNCTIONS = {"sin", "cos", "tan", "exp", "log", "ln"}
MEAN_WORDS = {"mean", "means", "meant", "meaning"}
SUBJECT = {"I", "you", "we", "they", "You", "We", "They"}
MODAL_OR_AUX = {"might", "could", "may", "shall", "probably", "just", "not", "'t", "is", "are",
                "to", "it", "It"}
WEAK = {"that", "this", "would", "which", ","}
DETERMINERS = {"the", "a", "an", "by", "its", "their", "of", "This", "That", "no", "The"}


def unit_kind(token):
    """'long' or 'short' for a unit of measure (a slash unit like '/m' counts as long), else None."""
    piece = token.replace("·", ".").split("/")[-1].split(".")[-1]
    if token.startswith("/") and piece in SHORT_UNITS:
        return "long"
    if piece in LONG_UNITS:
        return "long"
    if piece in SHORT_UNITS:
        return "short"
    return None


def token_at(raw, i):
    """The i-th token of the prefix, decoded and stripped of its spaces ('' before the start)."""
    return raw[i].strip() if i >= 0 else ""


def unit_before(raw, end):
    """The unit ending just before index `end`, skipping LaTeX markup; None if there is none."""
    j = end - 1
    while j >= 0 and token_at(raw, j) in MARKUP:
        j -= 1
    return unit_kind(token_at(raw, j)) if j >= 0 else None


def mean_strength(prev):
    """How strongly the word before 'mean' makes it the verb (negative) rather than the noun."""
    if prev in SUBJECT:
        return -7.0
    if prev in MODAL_OR_AUX:
        return -3.0
    if prev in WEAK:
        return -1.5
    if prev in DETERMINERS:
        return 0.0
    return -1.5


def step(carry, prefix, upstream):
    raw = prefix.token_strings          # tokens 0..t, decoded alone
    n = len(raw)
    cur = token_at(raw, n - 1)
    prev = token_at(raw, n - 2)
    prev2 = token_at(raw, n - 3)
    behind = unit_before(raw, n - 2)    # the unit the previous token follows
    if cur in ("²", "³"):
        if unit_kind(prev) == "long" or prev == "m":
            return carry, (6.0 if cur == "³" else 3.0)
    elif cur in CARETS:
        if unit_before(raw, n - 1) == "long":
            return carry, 4.5
    elif cur.isdigit():
        if prev in POWER_SIGNS and behind:
            return carry, (7.0 if behind == "long" else 4.0)
        if prev in POWER_SIGNS and prev2 in INVERSE_FUNCTIONS and cur == "1":
            return carry, 5.0
        if prev == "-" and behind:
            return carry, (6.0 if behind == "long" else 2.0)
        if unit_kind(prev) == "long" and cur in ("2", "3"):
            return carry, 6.0
        if n > 1 and raw[n - 2] == " " and behind == "long" and cur in ("2", "3"):
            return carry, 5.0
    elif cur in MEAN_WORDS:
        return carry, mean_strength(prev)
    elif cur == "about" and prev == "talking":
        return carry, -5.0
    elif cur == "to" and prev == "referring":
        return carry, -3.0
    return carry, 0.0

programs.sol:
"""Partial predictor for document structure, not a complete lexical model.

A document-opening 'Title:' has a particularly large positive colon response.
Source headers and tag labels are positive; initial runs of identical
whitespace or escaped-whitespace tokens are negative, as are middle-dot runs.
Conversation delimiters get smaller offsets.
Most ordinary text is approximated by a near-zero background value.
"""

READS = ()
SOURCE_HEADERS = frozenset(('package', 'using', 'import', '#include', 'module'))
DELIMITERS = {
    '<|im_start|>': -0.040,
    '<|im_end|>': 0.016,
    '<tool_call>': 0.041,
    '</tool_call>': -0.055,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, leading = 0, '', True
    else:
        _, position, previous, leading = carry
        leading = leading and token == previous

    word = token.strip()
    value = DELIMITERS.get(token, 0.0023)
    if len(token) >= 2 and set(token) == {'·'}:
        value = -0.541
    elif word == 'Tags':
        value = 0.45 if previous.strip() == 'Show' else 0.25
    elif word == 'permalink':
        value = 0.29

    if position == 0:
        if token == 'Title':
            value = 0.478
        elif word in SOURCE_HEADERS:
            value = 0.55
        elif word.startswith(('//', '/*')):
            value = 0.39
        elif token == '<|im_start|>':
            value = 0.218
    if leading:
        if token.isspace():
            value = -0.43 if '\t' in token else -0.10 if '\n' in token else -0.20
        elif token in ('\\t', '\\n', '\\r'):
            value = -0.65
    if position == 1 and previous == 'Title' and token == ':':
        value = 3.431
    return (doc, position + 1, token, leading), value

programs.haiku:
"""Layer-1 MLP down_proj component 5774: a near-silent, diffuse feature.

What it does: it is close to zero at almost every token (its causal importance is
~1e-6), so the program predicts 0 everywhere except at the first two tokens of each
document. There, the component's activation is set by the token's kind: punctuation
starts a document with a clear positive value, whitespace with a negative one, and
other tokens a small positive one. Those few values are the only regularity found.

Why it is this simple: the activation's variance is spread over many tokens with
no shared concept. Token class, script, position, repetition, and the previous token
each explain well under 1% of it on held-out text. The one lexical signal, the token
identity itself, needs a table of about 150k entries, which is not a concept.
"""

import unicodedata

READS = ()

# Activation at document positions 0 and 1, by the kind of token (fit on 1024 rows).
START = {"punct": 0.10, "space": -0.17, "word": 0.02}
SECOND = {"punct": 0.05, "space": 0.0, "word": 0.0}


def _kind(text):
    core = text.strip()
    if not core:
        return "space"
    if all(unicodedata.category(ch)[0] in "PS" for ch in core):
        return "punct"
    return "word"


def step(carry, prefix, upstream):
    # carry: (document id of the last token, its position within the document)
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos = 0
    else:
        pos = carry[1] + 1
    kind = _kind(prefix.token_strings[-1])
    if pos == 0:
        value = START[kind]
    elif pos == 1:
        value = SECOND[kind]
    else:
        value = 0.0
    return (doc, pos), float(value)

programs.sol:
"""Sparse local spelling and formatting motifs.

A single space after a newline/escape or quote is positive. Split
J/j words are selective: the small continuation table records strong name
and abbreviation spellings, rather than treating every J word alike.
Short ou/au/am joins after j, and ou/au/ao after ch, are negative.
Exclamations and ellipses
after function words are mildly positive. Separate rules describe
split Unicode marks, a Title: heading, and a weak document-start bias.
These are approximate training responses, not a general semantic category.
"""
READS = ()

# Literal continuations of J: Jena, JAX/JAXB, Jaff-, and letter acronyms.
J_CONTINUATIONS = {
    'ena': 1.25,
    'ax': 3.6,
    'AX': 2.2,
    'aff': 4.1,
    'F': 2.4,
    'EA': 3.7,
    'MS': 5.0,
}


FUNCTION_WORDS = frozenset(
    'the a an of to for in on at by with and or as is are we you '
    'that this from into which who than whose'.split()
)


def response(prev, byte_tail, text, raw, position):
    if position == 1 and prev == 'Title' and text == ':':
        return 4.284
    if text == ' ':
        if byte_tail.endswith(b'\\n'):
            return 0.847
        if prev.endswith('\n'):
            return 0.354
        if prev.endswith(('"', "'")):
            return 0.336
    if prev.lower().endswith('jo') and text.startswith('ach'):
        return 2.7  # the Joachim prefix
    if text.isalpha():
        lower = text.lower()
        if prev.lower().endswith('j'):
            if text in J_CONTINUATIONS:
                return J_CONTINUATIONS[text]
            if len(text) <= 3 and lower.startswith(('ou', 'au', 'am')):
                return -2.0
            if text.isupper():
                return 0.5
            if len(text) == 1 and text[0] in 'äöü':
                return 1.1
            return 0.12
        if prev.lower().endswith('ch'):
            if len(text) <= 3 and lower.startswith(('ou', 'au', 'ao')):
                return -1.6
    if text in ('!', '...') and prev.strip().lower() in FUNCTION_WORDS:
        return 0.6 if text == '!' else 0.33
    if text.strip().lower() == 'jou':
        return -0.93
    if raw == b'\xe0\xa8':  # unfinished Gurmukhi character
        return -0.98
    if byte_tail.endswith(b'\xe0\xb9') and raw == b'\x8a':
        return -4.7  # split Thai mai tri tone mark, ๊
    # Partial UTF-8 in the Han shell/money-radical region U+8C80..8D3F.
    if byte_tail.endswith(b' \xe8') and raw in (b'\xb2', b'\xb3', b'\xb4'):
        return 1.8
    if byte_tail.endswith(b'\xe2\x8d') and raw == b'\x9d':
        return 1.5  # APL comment sign ⍝
    if byte_tail.endswith(b' \xe2') and raw == b'\x99\x82':
        return 1.4  # male sign ♂
    if text == '··' and (prev == '··' or position == 0):
        return -0.886
    if position == 0:
        if text.isdigit():
            return -0.31
        return -0.04 if text.startswith(' ') else -0.14
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, byte_tail, position = '', b'', 0
    else:
        _, prev, byte_tail, position = carry
    text, raw = prefix.token_strings[-1], prefix.token_bytes[-1]
    value = response(prev, byte_tail, text, raw, position)
    state = (doc, text, (byte_tail + raw)[-8:], position + 1)
    return state, value

"""Approximate the document-start response, including uniform opening runs.

Words receive a negative initial pulse; whitespace, digits and punctuation
receive separate shape-based estimates. An opening run of paired middle dots
("··") receives a stronger negative estimate. Once a different token appears, predict zero: this deliberately
leaves the component's later token-specific variation unexplained.
"""
import unicodedata

READS = ()


def initial_response(text):
    word = text.strip()
    if text == '··':
        return -1.144
    if text == '<|endoftext|>':
        return -1.86
    if word.startswith('<|') and word.endswith('|>'):
        return -0.12
    if not word:
        if '\t' in text:
            return -0.42
        return 0.17 if '\n' in text else 0.08
    if word.isdecimal():
        return -0.06
    if all(unicodedata.category(c)[0] in 'PS' for c in word):
        return -0.27 if '\n' in text else -0.16
    return -0.37


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = initial_response(prefix.token_strings[-1])
        return (doc, token, value), value
    if carry[1] == token:
        return carry, carry[2]
    # The initial uniform run has ended; later repetitions do not count.
    return (doc, None, 0.0), 0.0

