programs.sol:
"""A local English grammatical-transition signal, not a grammar checker.

Number/conjugation clashes and missing finite verbs give positive predictions.
So do some perfectly grammatical constructions: subjunctive 'I were', auxiliary
inversion, and 'don't be'. Purpose infinitives and directed-object complements
are negative. These are short token-level cues, not a sentence-level parse;
local noun number can disagree with the actual sentence's subject. WordNet
supplies noun and verb morphology. Case/spacing checks avoid many code-variable uses.
Document-initial pronouns, verbs, and line/comment markers have separate offsets.
Lexical nuances and most non-English behavior are deliberately left unmodeled.
"""
from functools import lru_cache
import wordnet

READS = ()
SUBJECTS = {'i', 'you', 'we', 'they', 'he', 'she', 'it'}
OBJECTS = {'me', 'you', 'him', 'her', 'it', 'us', 'them'}
MODALS = {'can', 'could', 'may', 'might', 'must', 'shall', 'should',
          'will', 'would'}
AUXILIARIES = {'am', 'are', 'is', 'was', 'were', 'be', 'been', 'being',
               'has', 'have', 'had', 'do', 'does', 'did'}
CONTRACTED = {'isn': 'is', 'wasn': 'was', 'weren': 'were', 'aren': 'are',
              'doesn': 'does', 'don': 'do', 'hasn': 'has', 'haven': 'have'}
NOT_PLURALS = {'is', 'was', 'has', 'does', 'this', 'his', 'its', 'as', 'us',
               'yes', 'thus', 'unless', 'less', 'always', 'perhaps'}
DIRECTING = {'ask', 'tell', 'instruct', 'invite', 'urge', 'encourage',
             'advise', 'warn', 'teach', 'force', 'help', 'guide', 'lead'}
ENABLING_OR_GIVING = {'allow', 'enable', 'give', 'grant', 'offer', 'show'}
COMPLEMENTS = {'to', 'on', 'with', 'too', 'through', 'into', 'that', 'a',
               'the', 'this', 'my', 'your'} | OBJECTS


def normalize(s):
    s = s.strip().replace('’', "'")
    # Lowercase i is usually a programming variable, not the pronoun I.
    w = '<variable>' if s == 'i' else s.lower()
    return CONTRACTED.get(w, w)


@lru_cache(None)
def verb_form(w):
    if w in AUXILIARIES:
        return w
    if not w.isascii() or not w.isalpha() or len(w) < 3:
        return ''
    bases = wordnet.base_forms(w, 'verb')
    if not bases:
        return ''
    if w in bases:
        return 'bare'
    if w.endswith('ing'):
        return 'gerund'
    return 's_verb' if w.endswith('s') else 'past'


@lru_cache(None)
def noun_number(w):
    if not w.isascii() or not w.isalpha() or w in {'here', 'there'}:
        return ''
    if w == 's':  # A tokenized plural suffix.
        return 'plural'
    bases = wordnet.base_forms(w, 'noun')
    if bases:
        return 'plural' if any(b != w for b in bases) else 'singular'
    return 'plural' if w.endswith('s') and w not in NOT_PLURALS else ''


def predict(s, h, cr_only):
    w = normalize(s)
    form = verb_form(w)
    if s == '\r':
        return 5.8 if cr_only else 0.0
    if not h:
        if s in {'//\n', '#\n'}:
            return 8.8
        if w in SUBJECTS:
            return 1.0
        return 0.45 if form or w in {"'re", "'m", "'ve"} else 0.0
    if not s.startswith((' ', "'", '’')):
        return 0.0
    if s.strip() != 'I' and not s.strip().islower() and w not in AUXILIARIES:
        return 0.0
    p = h[-1]
    before = h[-2] if len(h) > 1 else ''
    lets = p == "'s" and before == 'let'
    negative_do = p in {"'t", 'not'} and before in {'do', 'does', 'did'}
    if negative_do and w == 'be':
        return 4.2
    if negative_do and w in SUBJECTS:
        return 3.0
    if w in {'were', 'are'} and p in {'i', 'he', 'she', 'it'}:
        return 3.4
    number = noun_number(p)
    plural = p in {'you', 'we', 'they', 'these', 'those'} or number == 'plural'
    if w in {'is', 'has', 'does', 'was'} and (plural or p == 'i'):
        if p in SUBJECTS:
            return {'is': 1.65, 'has': 1.1, 'does': 4.0,
                    'was': 0.0 if p == 'i' else 5.0}[w]
        return {'is': 0.65, 'has': 0.9, 'does': 0.38, 'was': 0.74}[w]
    if w in {'are', 'were'} and number == 'singular':
        return 0.2
    if p in MODALS:
        if form == 'gerund':
            return 2.7
        if form in {'is', 'has', 'does', 'are'}:
            return 3.2
        if form in {'past', 's_verb', 'was', 'were'}:
            return 1.1
        if w in {'in', 'on', 'at', 'within', 'under', 'a', 'the', 'an'}:
