    q = before if before in SUBJECTS and 'adverb' in wordnet.parts_of_speech(p) else p
    if q in SUBJECTS and form in {'gerund', 'being', 'been'}:
        return 1.1 if q == 'i' else 0.4
    if w == 'not' and (q in SUBJECTS or p == "'d" or lets):
        return 1.7
    if w == 'be':
        if lets:
            return 3.1
        if p == 'please':
            return 1.6
        if p in SUBJECTS:
            return 0.9
    if p == 'i' and w in SUBJECTS | OBJECTS | {'a', 'an', 'the'}:
        return 0.8
    if p in SUBJECTS and form == 's_verb':
        return 0.35
    if p == 'me' and form in {'bare', 'be', 'have', 'do'}:
        return 0.24
    if w in SUBJECTS and p in {'is', 'are', 'was', 'were', 'does', 'do', 'did'}:
        return 0.21
    if w in {'in', 'on', 'at', 'for', 'with', 'from'} and p in {'which', 'that'}:
