        h, cr_only = [], True
    else:
        _, h, cr_only = carry
    value = predict(s, h, cr_only)
    h = (h + [normalize(s)])[-14:]
    return (doc, h, cr_only and s == '\r'), float(value)

"""Mostly quiet; negative on local repetitions of the letter t.

The strongest rule recognizes consecutive literal backslash-t tab escapes.
Weaker rules recognize neighboring t-initial fragments and continuations
of fragments containing two t letters. Common t-initial grammatical and
number words are excluded; the continuation rule also excludes test prefixes.
A document-start offset and the initial Title: label are handled separately.
