import re

READS = ()
FUNCTION_WORDS = {
    'to', 'too', 'the', 'this', 'that', 'these', 'those', 'then', 'than',
    'there', 'their', 'they', 'them', 'through', 'though', 'thus',
}
NUMBER_WORDS = {
    'two', 'three', 'ten', 'twelve', 'thirteen', 'twenty', 'thirty', 'thousand',
}

def t_word(word):
    return (word.startswith('t') and len(word) > 1
            and word not in FUNCTION_WORDS | NUMBER_WORDS)


