        value = 0.17 if text.strip().isalpha() else 0.12
    else:
        _, previous, recent, previous_started, title = carry
        value = 0.002

    words = list(re.finditer('[a-z]+', low))
    old_words = re.findall('[a-z]+', previous)
    word = words[0][0] if words else ''
    old_word = old_words[-1] if old_words else ''
    continuation = bool(low and low[0].isalpha() and previous
                        and previous[-1].isalpha())
    before_t = (previous_started and t_word(old_word)
                and not old_word.startswith('th') and previous != '\\t')
    if t_word(word) and low != '\\t':
        if word.count('t') > 1:
            value -= 0.05
        if before_t:
            value -= 0.32
        elif 't' in old_word.replace('th', ''):
            value -= 0.05
    if (before_t and continuation and text[0].islower()
            and old_word.count('t') > 1
            and old_word not in {'test', 'tests', 'testing'}):
        value -= 0.28

