        value = -3.69
    title = text == 'Title' and first
    if title:
        value = 0.54

    started = bool(words and (words[-1].start() > 0 or not continuation))
    return (doc, low, (recent + text)[-24:], started, title), value

"""Detect short 'pr'/'pro' spelling fragments, also across token boundaries.

The corresponding Cyrillic, Greek, Japanese and Korean spellings count too.
Short pro fragments are positive; long words containing them are much weaker.
Completing pr with an o-like vowel across a token boundary is especially strong.
Only the current unfinished word is remembered; documents reset the memory.
"""
import codecs
import re
from anyascii import anyascii

READS = ()


def romanize(text):
    # The extra vowels in Japanese/Korean loanword spellings represent pr.
    text = text.replace('プ', 'p').replace('프', 'p').replace('로', 'ro')
    return anyascii(text).lower()


def response(token, word):
    s, p = romanize(token), romanize(word)
    cyrillic = any(c in token + word for c in 'пПрР')
    nonlatin = cyrillic or any(c in token + word for c in 'πρΠΡプロ프로')
    i = s.rfind('pr')
    if i >= 0:
        tail = s[i + 2:]
        n = len(tail)
        if not tail:
            if cyrillic:
                return .85 if token[:1].isspace() else .3
            return .5 if token.islower() else .15
        if tail.startswith('o'):
            levels = (0, 4.9, 3.9, 1.8, .35) if cyrillic else (0, 1.9, 1.2, .27, .1)
            return levels[min(n, 4)]
        if tail.startswith('a') and n <= 2:
            return .7 if n == 1 else .4
        if cyrillic and tail == 'i':
            return -.25
        return .1
    if not s or not s[0].isalpha():
        return 0.0
    split = p.endswith('p') and s.startswith('r')
    if p.endswith('pr') or split:
        tail = s[1:] if split else s
        n = len(tail)
        if not tail:
            return 2.4 if nonlatin else 1.0
        if tail.startswith('o'):
            if nonlatin:
                return (0, 8.4, 8.0 if not split else 4.6, 5.5, 3.0)[min(n, 4)]
            return (0, 6.8, 4.8, 3.1, .6)[min(n, 4)]
        if tail[0] in 'au':
            return (0, 3.5, 2.2, 1.2, .2)[min(n, 4)]
        if tail.startswith('e'):
            return -.6 if cyrillic and not split else 0.0
        if tail.startswith('i'):
            return .6 if cyrillic else .1
        return 1.5 if n <= 3 else .1
    if p.endswith('pro'):
        n = len(s)
        return (0, 4.8 if cyrillic else 3.3, 2.3, .4, .1)[min(n, 4)]
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')('replace')
        word = ''
    else:
        _, decoder, word = carry
    token = decoder.decode(prefix.token_bytes[-1])
    value = response(token, word)
    # Keep only the final uninterrupted run of letters.
    tail = re.search(r'[^\W\d_]+$', word + token, re.UNICODE)
    word = tail.group()[-20:] if tail else ''
    return (doc, decoder, word), float(value)

