"""Document-start token kinds. The component is negative on the first token of a document,
more so for capitalised words, ALL-CAPS words and punctuation, less so for lowercase words,
and near zero for CJK or mixed tokens. Everywhere else it is near zero."""
READS = ()

def kind_value(s):
    core = s.strip()
    if "�" in s:
        return 0.06
    if core and all(not c.isalnum() for c in core):
        return -0.2
    if not (core.isascii() and core.isalpha()):
        return -0.05
    if core[0].isupper():
