"""Partial approximation of a mixed early-layer detector using text rules.

The main signals are digit-five contexts, five-family words, closing quotation
punctuation, printf conversions, and import/markup syntax. A short text tail
supplies context; document boundaries reset it. Other lexical and contextual
variation is left unmodeled.
"""
import re

READS = ()
FIVE = re.compile(
    r'(?i)(?:\b|[-_])'
    r'(five|fives|fifth|fifteen|fifteenth|fifty|fifties)$'
)
PRINTF = re.compile(r'%[-+#0 ]*\d*(?:\.\d+)?[diuoxXfFeEgGaAcspvqrwb]$')
ANGLE = re.compile(r'''\s*['"(>]*<''')
QUOTE = re.compile(r'''[,，.。!?！？](?:["”“']|'')''')


