    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, prev, before = 0, '', ''
    else:
        _, pos, prev, before = carry
    s = prefix.token_strings[-1]
    word = s.strip()
    value = -0.001 - 0.058 * (pos == 0)
    if s.isdecimal():
        value -= 0.011

    # Five as a digit: attached identifiers differ from decimals and ordinary numbers.
    if s == '5':
        value += 0.147
        last = before[-1:]
        if last.isalpha():
            value += 0.037
            if last.isascii():
                value += 0.437
            if re.search(r'[A-Za-z]{2,}$', before):
                value += 0.134
        elif last.isdigit():
            value -= 0.084
        elif last == '.':
            value -= 0.357
        elif not last or last.isspace():
            value += 0.086
        if prev == '6':
            value += 0.453
        if pos == 0:
            value = -0.754
    if word and FIVE.search(before + s):
        value += 0.261
        if s[:1].isspace() and word[:1].isupper():
            value += 0.229
        if before.endswith(('f', 'F')):
            value += 0.197
    if word.lower() == 'friday':
        value += 0.363
    if s == '*****':
        value += 0.865

    # Especially commas at the end of quoted speech, including split quotes.
    split_quote = s in ('“', '”', '"', "'") and before.endswith(',')
    if QUOTE.fullmatch(word) or split_quote:
        value -= 0.377
        if word.startswith(',') or split_quote:
            value += 0.677
        if before.rstrip(',')[-1:].isalpha():
            value += 0.369
        if word.endswith(('”', '“')):
            value += 0.105

    if word == 'import':
        value += 0.081
        if pos == 0:
            value += 0.507
        if before.rstrip().endswith(('"', "'")):
            value += 0.205
    if '\n' not in s and word == '{':
        if re.search(r'\bimport\b[^;{}\n]*$', before):
            value += 1.286
        if prev.strip() in ('const', 'let'):
            value += 0.663
    if word == '*' and prev.strip() == 'import':
        value += 0.319
    line = before.rsplit('\n', 1)[-1]
    if '\n' not in s and ANGLE.fullmatch(s):
        value += 0.05
        if not line.strip(' +-\t0123456789'):
            value += 0.374
            if s.startswith(' '):
                value += 0.536
    if word == 'for' and not line.strip():
        value += 0.364

    # The conversion letter must actually be inside this token, not after a space.
    if s and s == word and s[-1] in 'diuoxXfFeEgGaAcspvqrwb':
        if PRINTF.search(before + s):
            value += 1.397
            if s[-1] in 'di':
                value += 0.286
            if s[-1] == 'v':
                value += 0.273
            if s[-1] == 's':
                value += 0.015
    if s in ('d', 'f', 'e', 'g', 's'):
        if re.search(r'\{:[^{}]*[dfegs]$', before + s):
            value += 0.873

    # Dot leaders and horizontal padding between columns.
    if s and set(s) == {'·'} and (pos == 0 or prev == s):
        value += 0.521
    if s.isspace() and 8 < len(s) <= 20 and set(s) == {' '}:
        if before and not before[-1].isspace():
            value += 0.086

    # Two unusually strong, reproducible document-opening prefixes.
    if pos == 0 and s == 'Title':
        value = -1.4104
    if pos == 1 and prev == 'Title' and s == ':':
        value = 7.7571
    if pos == 1 and prev == '1' and s == '2':
        value = 4.0953
    return (doc, pos + 1, s, (before + s)[-120:]), float(value)

