    '<filename>': 0.421,
    '<re': 0.400,
    '<repon': 0.175,
    '<reponame': 1.679,
    '<reponame>': 0.199,
    '<gh': 0.496,
    '<gh_st': 0.231,
    '<gh_stars': 1.444,
    '<gh_stars>': 0.283,
