"""Sparse annotation/declaration cues, plus Japanese written inflection endings.

Code metadata openers are negative, especially Rust attributes and indented
annotations. Hiragana following a Han character is treated as okurigana:
conjugation stems are stronger than particles or complete endings. Other
positions are left near zero. Only recent text in the same document is used.
"""
import re
from functools import lru_cache
import regex

READS = ()


PARTICLES = frozenset(('の', 'は', 'が', 'を', 'と', 'に', 'で', 'も', 'へ',
                       'や', 'な', 'から', 'まで', 'など', 'には', 'とは',
                       'では', 'ため', 'ので', 'こと', 'もの', 'です', 'ます',
                       'でした', 'ました', 'でも', 'だけ'))
HAN = regex.compile(r'\p{Script=Han}$')
HIRA = regex.compile(r'\p{Script=Hiragana}+$')
CODE = re.compile(r"\b(?:public|private|protected)\s+\w+"
                  r"|\bnamespace\s+[\w.]+\s*\{"
                  r'|\busing\s+[A-Z]\w*[.;]|```(?:cs|csharp)\b')
NEWLINE = re.compile(r'\n|\\+[nr]')
NUMBERED = re.compile(r'^\s*\d+\t(.*)$')


@lru_cache(maxsize=65536)
def token_kind(token):
    s = token.strip()
    hira = s.rstrip('\ufffd')
    if hira and HIRA.fullmatch(hira):
        return 'kana', hira
    if (re.fullmatch(r'@[A-Za-z_]\w*', s) or
            s in ('#[', '#![', '[', '([', '(@', '@', '#', '///', 'with',
                  'operator', 'template', 'Override', 'Test') or
            s.startswith('.')):
        return 'code', s
    return '', s


def activation(token, before):
    family, s = token_kind(token)
    if not family:
        return 0.0
    # Shape-based okurigana approximation, not a Japanese grammar parser.
    if family == 'kana':
        if not HAN.search(before):
            return 0.0
        if s in PARTICLES:
            return -0.1
        if len(s) > 1:
            if s == 'んで':
                return -4.0
            if re.fullmatch('[まわ]り', s):
                return -3.1
            return -0.3 if len(s) == 2 else 0.0
        if s == 'ば':
            return -11.9
        if s == 'べ':
            return -7.6
        # i-, a- and e-row conjugation fragments have different strengths.
        if s in 'きぎじちぢびぴり':
            return -6.4
        if s in 'しみ':
            return -3.9
        if s == 'い':
            return -1.6
        if s in 'かさたまらわ':
            return -4.8
        if s in 'えけげせてねへめれ':
            return -2.8
        if s == 'ん':
            return -7.9
        if s == 'っ':
            return -4.2
        return -1.4

    # Numbered listings and escaped newlines still delimit logical code lines.
    logical = NEWLINE.split(before)[-1]
    numbered = NUMBERED.match(logical)
    line = numbered.group(1) if numbered else logical
    line = line.removeprefix('+')
    start = not line.strip()
    indent = len(line) + len(token) - len(token.lstrip())
    comment = line.lstrip().startswith(('*', '//', '/**'))
    code = bool(CODE.search(before))
    if s == '#![':
        return -3.4
    if s == '#[':
        if start and before.rstrip().endswith(')'):
            return 0.0
        if start and r'\n' in before[-80:]:
            return -12.8
        if start:
            return -14.4 if numbered else -18.6
        return -11.1
    if re.fullmatch(r'@[A-Za-z_]\w*', s) or s in ('@', '(@'):
        if len(s) > 1 and s != '(@':
