                    return -7.0
                return -11.5
            if '\t' in line:
                return -10.4 if code else -4.3
            if before.rstrip().endswith(('}', ')', ';')):
                return -4.0
            return -1.5
        if (line.rstrip().endswith(('(', ',')) or s == '(@') and code:
            return -5.2
        return 0.0
    # C# attributes, distinguished from ordinary brackets by declaration context.
    if s in ('[', '([') and code and '\n' not in token:
        if start and (before.rstrip().endswith((';', '{', '}', ']', '/', '>')) or
