            return -15.4 if indent else -8.0
        if (s == '([' or line.rstrip().endswith(',')) and re.search(
                r'\b(?:public|private|protected)\b', line):
            return -6.8
    if s in ('.annotation', '.annotations') and 'import ' in logical:
        return -9.1
    if s == '.junit' and 'import ' in logical:
        return -4.4
    if s == '.io' and before.endswith('java'):
        return -2.3
    if s == '.view' and before.endswith('android'):
        return -2.6
    if s == '.http' and before.endswith('servlet'):
        return -2.5
    if s in ('Override', 'Test') and before.rstrip().endswith('@'):
        return -3.3 if s == 'Override' else -2.8
    if s == '///' and start:
        return -1.0 if indent >= 6 else -0.2
    if s == '#' and start and code:
        return -2.3
    if s == 'operator' and re.search(r'(?:[&*]|::|\b(?:void|bool|double))\s*$', before):
        return -5.6
    if s == 'template' and (before.rstrip().endswith(('->', '::')) or
                            start and ('namespace ' in before or '#include' in before or
                                       'std::' in before or
                                       not token[0].isspace() and
                                       before.rstrip().endswith((';', '}')))):
        return -7.6
    if s == 'with' and start and indent >= 3:
        return -3.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = b''
    else:
        tail = carry[1]
    token = prefix.token_strings[-1]
    family, _ = token_kind(token)
    value = activation(token, tail.decode('utf-8', 'replace')) if family else 0.0
    return (doc, (tail + prefix.token_bytes[-1])[-1024:]), value

