import re

READS = ()
MODIFIERS = {'public', 'private', 'protected', 'abstract', 'final', 'partial'}
EXPORTS = {'const', 'default', 'type'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
