        if prev == 'public' and tail.endswith(prev):
            source = re.search(r'(?:^|\n)(?:import |using |package )', tail)
            value = (1.7 if source else 1.3) if line == 'public' else 0.95
        elif prev == 'export':
            value = 1.0 if line == 'export' else 0.5
        elif prev in MODIFIERS and tail.endswith(prev):
            value = 1.45 if 'public ' in line else 0.4
        elif prev == 'default' and 'export default' in line:
            value = 1.15
        elif token == 'class' and not line.strip() and tail:
            value = 0.45 if re.search(r';\s*$', tail) else 0.2
    elif prev == 'export' and word in EXPORTS:
        value = 0.55
    elif word in {'void', 'int', 'float'} and prev in MODIFIERS | {'static'}:
        value = 0.18 if word == 'void' else 0.12 if word == 'int' else 0.5
        if prev == 'static' and word == 'void':
            value = 0.3
        elif prev == 'final' and word == 'int':
            value = 0.65
    elif word == 'static' and prev in MODIFIERS:
        value = 0.13
    elif word == 'namespace':
        value = 0.7 if re.search(r';\s*$', tail) else -0.4 if not tail else 0.0
    elif word == 'using' and tail.endswith((';\n', ';\r\n')):
        value = 0.23
    elif word == 'def' and not tail:
        value = 1.99

    if word == 'edited' and prev == 'Last':
        value = 1.3
    elif word == 'Posted' and prev == 'Originally':
        value = 0.82
    elif word == 'by':
        if prev == 'Posted':
            value = 1.15 if 'Originally Posted' in tail else 0.35
        elif prev == 'edited' and 'Last edited' in tail:
            value = 1.3
        elif re.search(r'(?:^|\n)(?:posted|asked|Reviewed|Written)$', tail):
            value = 0.5
    elif word == 'post':
        if tail.endswith("Expert's"):
            value = 3.8
        elif prev == 'Last':
            value = 1.1
    elif word == 'Reply' and prev == 'Expert':
        value = 1.4
    elif word == 'Message' and prev == 'Author':
        value = 1.2
    elif word == 'POST' and prev == 'QUESTION':
        value = 1.7
    elif token.rstrip() == ':':
        if re.search(r'(?:^|\n)Question$', tail):
            value = 1.6 if 'Title:' in tail else 1.15
        elif re.search(r'(?:^|\n)Answer$', tail):
            value = 0.95 if re.search(r'\n[A-D]\.', tail) else 0.5
        elif re.search(r'(?:^|\n)(?:question|user)$', tail):
            value = 0.5
        elif prev == 'edited' and 'Last edited' in tail:
            value = 0.78
        elif prev in {'Institutions', 'Kudos', 'author'}:
            value = 0.6
        elif tail.endswith(('More information', 'You are watching')):
            value = 1.0
        elif prev == 'preview':
            value = 2.8
        elif prev == 'is' and 'question is' in tail:
            value = 0.6

    if word == 'SOFTWARE' and re.search(r'DEALINGS[\s\S]{0,80}THE$', tail):
        value = 1.1
    elif word == 'License' and 'permissions and limitations under the' in tail:
        value = 0.75
    elif word == 'DAMAGE' and 'POSSIBILITY OF' in tail and prev == 'SUCH':
        value = 0.7
    elif token == '://' and prev.lower() in {'http', 'https'}:
        value = 0.87 if prev.lower() == 'https' else 0.56
    elif token == '··':
        value = -1.0
    elif token == '#' and not tail:
        value = 0.7
    elif token == '<|im_start|>':
        value = -0.226 if not tail else -0.052

    return (doc, (tail + token)[-500:]), value

programs.haiku:
"""Layer 1, MLP down_proj, component 5786.

What it does: a sparse detector for the word that sets up a name, identifier or URL
that is about to be spelled out. It is near zero almost everywhere and fires on a few
recognisable spots:

  * "://" after a URL scheme (https://, http://): about +0.75
  * "class" after "public" ("public class", a Java/C# class declaration): about +1.5
  * "const", "default", "class", "interface" after "export": about +0.6 (class ~0.5)
  * "by" in "Posted by" / "edited by" / "Reviewed by" (forum attribution): about +1.0
  * "Posted" after "Originally" ("Originally Posted by"): about +0.85
  * "edited" after "Last" ("Last edited:"/"Last edited by"): about +1.3
  * ":" after a label such as "Answer", "Question", "Kudos": about +0.8
  * a code opener as the first token of a document ("#", "def", "print", "import",
    "namespace"): about +0.6
  * "namespace" after ";" (end of a C# using block): about +0.9

Everywhere else it predicts 0. Activation is noisy and small elsewhere (sd about 0.04),
so this only captures the large spikes.
"""

READS = ()

DECL_MODIFIERS = {"public"}
EXPORT_DECLS = {"const", "default", "class", "interface", "function", "let", "var"}
ATTRIBUTION = {"Posted", "posted", "edited", "Reviewed"}
LABELS = {"Answer", "Question", "Kudos", "udos"}
CODE_OPENERS = {"#", "#include", "#ifndef", "#from", "#pragma", "def", "print", "namespace", "import"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip()
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    # A new document starts where the document id changes (and at the row's first token).
    new_doc = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    value = 0.0
    if tok == "://":
        value = 0.75
    elif word == "class" and prev in DECL_MODIFIERS:
        value = 1.5
    elif word in EXPORT_DECLS and prev == "export":
        value = 0.6
    elif word == "by" and prev in ATTRIBUTION:
        value = 1.0
    elif word == "Posted" and prev == "Originally":
        value = 0.85
    elif word == "edited" and prev == "Last":
        value = 1.3
    elif tok == ":" and prev in LABELS:
        value = 0.8
    elif new_doc and word in CODE_OPENERS:
        value = 0.6
    elif word == "namespace" and prev == ";":
        value = 0.9
    return carry, float(value)

programs.sol:
"""Likeness/form words, chiefly Chinese 样/樣 and Japanese 様/よう.

Use the visible morpheme and its immediate grammatical surroundings, not
word meaning in general: a fused compound often responds less than a separate
character. Also approximate weaker appearance cues, related-looking Han
characters, and a separate negative bias on initial tokens/repeated symbols.
"""
import codecs
import regex

READS = ()


def form_cue(token, before):
    word = token.replace('樣', '样')
    if word == '样':
        if before.endswith(('啥', '哪', '咋', '么', '麼', '多')):
            return 10.0
        if before.endswith(('采', '试', '試')):  # sampling/testing
            return 3.0
        return 6.0 if before.endswith(('一', '同', '照')) else 8.0
    if word == '样的':
        return 2.2 if before.endswith('一') else 7.0
    if '样' in word:
        if '样本' in word:  # statistical sample, rather than likeness
            return 0.3
        if any(part in word for part in ('样式', '多样性', '多样化')):
            return 1.2
        if word.startswith('同样'):
            return (5.7 if '樣' in token else 3.3) - word.count('的')
        return 5.2 if len(word.strip('的')) == 2 else 3.5
    if token == '様':
        if before.endswith('仕'):  # 仕様: specification
            return 1.4
        return 6.0 if regex.search(r'\p{Hiragana}$', before) else 4.0
    if token in ('どんな', 'どのような'):  # what kind of
        return 3.8
    if 'よう' in token:
        lead, ending = token.split('よう', 1)
        if not ending:
            return 2.0 if not lead else 0.2
        if ending == 'な':
            return 2.4 if lead == 'の' else 0.85 if not lead else 0.55
        if ending == 'に':
            return 0.4 if lead.endswith('ない') else 1.1
    if token == 'さま':
        return 0.65 if before.endswith('客') else 2.5
    if token == 'う':  # completing そう/ふう: seeming/manner
        if before.endswith('そ'):
            return 3.4
        return 2.0 if before.endswith('ふ') else 0.0
    # Grammatical endings completing a form/appearance expression.
    if before.endswith(('样', '樣', '様')):
        if token == '子':
            return 3.2
        if token in ('的', 'な', '貌'):
            return 1.6
    if '般' in token:
        return 0.7 if '一般' in token else 3.2 if token == '般' else 1.5
    if token in ('状', '款'):
        return 1.0
    if '如何' in token or token == '漂亮':
        return 0.6
    if token in ('洋', '漾', '祥'):  # visually related to 样, sharing 羊
        return 2.7
    if token == '่าง' and before.endswith('อย'):  # Thai อย่าง: manner/like
        return 1.4
    return 0.0


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        pending, before, first, initial = b'', '', raw, True
    else:
        _, pending, before, first, initial = carry
        initial = initial and raw == first
    data = pending + raw  # complete characters split across byte tokens
    token, used = codecs.utf_8_decode(data, 'ignore', False)
    value = form_cue(token, before)
    if initial and value == 0.0:
        if token == '\t':
            value = -2.5
        elif token == '··':
            value = -3.7
        elif token.strip().isdigit():
            value = -0.03
        else:
            letters = token.strip().isascii() and token.strip().isalpha()
            value = -0.46 if letters else -0.3
    return (doc, data[used:], (before + token)[-16:], first, initial), value

programs.haiku:
"""layers.1.mlp.down_proj:5787 -- the "like / such / in this manner" feature.

What it does
  The component writes a large positive value onto the token that completes a word
  meaning "in this manner / of this kind / like / the same as":
    Chinese  样 / 樣 in 这样, 那样, 一样, 同样, 怎样, 样子, 什么样 (strongest on the bare 样/樣)
             般 in 如刀削般 / 这般 ("like, as if")
    Japanese 様 on its own, and よう / ような / ように / のような ("like", "so as to")
             どんな ("what kind of")
  Noun uses of 样 (样本 sample, 样品 product, 样式 style) do not fire, and 一般 ("general")
  barely does. Three characters that share the 羊 part with 样 (洋, 漾, 祥) fire weakly;
  other 羊-containing characters (美, 差, 善) do not.
  A second, rarer effect: inside a long run of one repeated symbol-only filler token
  (a line of '··········' or '⎯⎯⎯⎯'), the component goes negative.
  Everything else is predicted as 0. The values are the mean activations per group.

Why this is the right picture
  Activation is the component's contribution to the residual stream. Its large positive
  values sit on the manner/similarity words above; its negative values sit on repeated
  filler runs. The small background (|x| < 0.3) is not captured by any word list.
"""
READS = ()

NOT_MANNER_NOUN = {"样本", "样品", "样板", "样式", "样机", "样张", "样片"}
LIKE_JAPANESE = {"よう", "ような", "ように", "のような", "のように", "どのような", "どのように", "このような"}
LOOKALIKES = {"洋", "漾", "祥"}
RUN_LIMIT = 100  # a run longer than this counts as a filler run


def manner_value(s):
    """Activation for a single token string, from its manner/similarity meaning."""
    if s in NOT_MANNER_NOUN:
        return 0.0
    if s in ("样", "樣"):
        return 8.4
    if "样" in s or "樣" in s:
        return 4.8
    if s == "般":
        return 2.8
    if s == "様":
        return 4.1
    if s == "どんな":
        return 4.0
    if s in LIKE_JAPANESE:
        return 1.5
    if s in LOOKALIKES:
        return 2.8
    return 0.0


def is_symbol_filler(s):
    """True for a token made only of punctuation or symbol characters, e.g. '··', '⎯', ' _'."""
    import unicodedata

    s = s.strip()
    return len(s) > 0 and all(unicodedata.category(ch)[0] in "PS" for ch in s)


def step(carry, prefix, upstream):
    token = prefix.token_ids[-1]
    doc = prefix.document_ids[-1]
    # carry = (last token id, length of its run so far, document label)
    if carry is None or carry[2] != doc or carry[0] != token:
        run = 1
    else:
        run = carry[1] + 1
    carry = (token, run, doc)
    s = prefix.token_strings[-1]
    if run > RUN_LIMIT and is_symbol_filler(s):
        return carry, -1.0
    return carry, float(manner_value(s))

programs.sol:
"""Predict a local abbreviation / letter-fragment response.

The second short letter piece is strongest, especially in capitals. Common
English pairs and later pieces of a letter sequence are damped. Capital
letters followed by a capital-plus-s get a plural-abbreviation response;
two-letter capitals and unfamiliar two-letter words respond mildly. Separate offsets handle document starts
and hexadecimal-prefix fragments. All state resets at document boundaries.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency
READS = ()

@lru_cache(maxsize=32768)
def letters(s):
    return bool(s) and s.isalpha() and all(
        any(script in unicodedata.name(c, '')
            for script in ('LATIN', 'GREEK', 'CYRILLIC')) for c in s)

@lru_cache(maxsize=32768)
def common(s):
    return zipf_frequency(s, 'en')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    reset = carry is None or carry[0] != doc
    tail = '' if reset else carry[1]
    chain = 0 if reset else carry[2]
    m = re.fullmatch(r'([\s.\-_/]*)([^\W\d_]+)', s)
    value = 0.0
    next_chain = chain if s == '.' else 0
    if m and letters(m[2]):
        sep, z = m.groups()
        pm = re.search(r'([^\W\d_]+)([. ]*)$', tail)
        p = pm[1] if pm and letters(pm[1]) else ''
        if len(z) == 1 and (not sep or sep.isspace() or sep == '.'):
            next_chain = chain + 1 if len(p) == 1 else 1
        if len(z) == 1 and len(p) == 1:
            if not sep:
                value = 2.7 if z.isupper() and p.isupper() else 1.2
                if not z.isupper() and common(p+z) > 4.5:
                    value *= 0.25
            elif sep == '.':
                # A letter following a dot inside an initialism.
                dotted = bool(re.search(r'[^\W\d_]\.[^\W\d_]$', tail))
                value = 0.1 if dotted else 2.5 if z.isupper() else 0.7
                if (p+z).lower() in ('ie','eg'):
                    value = 0.0
            elif sep.isspace():
                if p.isupper() and z.isupper():
                    value = 1.2 if p.lower() in 'aeiou' else 1.7
                else:
                    value = 0.35
            elif sep == '-':
                value = 1.2 if z.isupper() else 0.55
            pair_freq = common(p+z)
            if not sep.isspace() and pair_freq > 5.0:
                value *= 0.2
            elif not sep.isspace() and pair_freq > 4.5:
                value *= 0.6
            if chain >= 2:
                value *= 0.3
        elif len(z) == 2:
            plural_initial = (z[0].isupper() and z[1] == 's'
                              and len(p) == 1 and p.isupper() and not sep)
            if plural_initial:
                value = 3.5
            elif sep or not tail or not tail[-1:].isalpha():
                if z.isupper():
                    value = 0.30
                elif common(z) < 3.6:
                    value = 0.27
    prev = '' if reset else carry[3]
    if prev == '0' and re.fullmatch(r'x[0-9a-fA-F]*', s):
        if len(s) == 1:
            value = 0.6
        elif len(s) == 2:
            value = -2.5
    if reset:
        if letters(s) and len(s) > 1:
            value = 0.2 if s.isupper() else -0.3
        else:
            value = -0.1
    return (doc, (tail+s)[-48:], next_chain, s), value

"""Approximate a document-start bias and small token-form effects.

At a document's first token, predict a usually negative write depending on
formatting, case, script and English word frequency. Code headers are the
strongest negative case. Later predictions are near zero, with small offsets
for case, numbers, markup, code literals, possibility modals and -ing endings.
This is a coarse approximation, not an account of individual word identities.
"""
import regex
from wordfreq import zipf_frequency

READS = ()
DECLARATIONS = frozenset(
    'class package namespace interface struct enum typedef'.split()
)
CYRILLIC = regex.compile(r'\p{Script=Cyrillic}')


def initial_value(s):
    t = s.strip()
    if t in DECLARATIONS or t.startswith(
        ('//', '/*', '#!', '#pragma', '"""', '<?')
    ):
        return -0.96
    if not t:
        if '\n\n' in s:
            return 0.07
        if '\n' in s:
            return -0.30
        if s == ' ':
            return 0.035
        return -0.40
    if t.startswith('<|'):
        return -0.135
    if '\ufffd' in t:
        return -0.065
    if CYRILLIC.search(t):
        return -0.20
    if not t.isascii():
        return -0.01
    if t.isdigit():
        return -0.20
    if t.isalpha():
        if t.istitle():
            return -0.02 if s[0].isspace() else -0.085
        if t.isupper():
            return -0.07 if s[0].isspace() else 0.115
        return -0.07 if s[0].isspace() else -0.065
    if any(c.isalpha() for c in t):
        return -0.30
    return -0.20


LITERALS = frozenset('true false null none nil undefined'.split())
POSSIBILITY = frozenset('may might could can'.split())
MARKUP = regex.compile(r'</?[^<>]+>')


def ordinary_value(s):
    t = s.strip()
    value = 0.003
    if t.istitle():
        value -= 0.007
    if t.isdigit():
        value -= 0.006
    if s.startswith(' '):
        value -= 0.0025
    if MARKUP.fullmatch(t):
        value += 0.043
    if t.startswith('<|'):
        value -= 0.064
    if t.lower() in LITERALS:
        value -= 0.036
    if t.lower() in POSSIBILITY:
        value -= 0.019
    if t.isalpha() and len(t) >= 8:
        value -= 0.005
    if t.isascii() and t.isalpha() and len(t) > 5 and t.endswith('ing'):
        value += 0.011
    if '\ufffd' in s:
        value += 0.012
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry != doc
    if not first:
        return doc, ordinary_value(s)
    value = initial_value(s)
    t = s.strip()
    if t.isascii() and t.isalpha():
        frequency = zipf_frequency(t.lower(), 'en')
        value -= 0.11 * (frequency >= 4) + 0.14 * (frequency >= 6)
    return doc, value

programs.haiku:
"""Conjunction-follower, pronoun-only, stronger: after 'and'/'&', a pronoun or 'beyond' gets -1.0."""
READS = ()
CONJ = {' and', ' And', 'And', '&', ' &', 'und', 'と'}
PRON = {' I', ' us', ' you', ' we', ' her', ' beyond', ' above', ' me', ' them', ' him'}
def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) >= 2 and toks[-2] in CONJ and toks[-1] in PRON:
        return carry, -1.0
    return carry, 0.0

programs.sol:
"""Approximate several shallow spelling and document-boundary effects.

Most ordinary tokens get a small background value. Document openings have a
negative pulse, especially bare Latin words and indentation. The spelling
family beginning 'cust' is positive; some following suffixes are negative.
Middle dots, Arabic shadda, and an opening 'Title:' have separate responses.
This is a coarse predictor, not a complete account of the rare large spikes.
"""
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
KANA = regex.compile(r'\p{Script=Katakana}')


def stem(text):
    return text.strip().lstrip('._-(<').lower()


def opening(s):
    word = s.strip()
    if s.startswith('<|'):
        return -0.035
    if s.startswith('#!'):
        return -1.0
    if s.startswith('#'):
        if len(s) > 1 and s[1].isalpha():
            return -0.85
        return -0.63 if not s.startswith('##') else -0.43
    if not word:
        if '\t' in s:
            return -0.50
        if '\n' in s or '\r' in s:
            return 0.03
        return 0.11 if len(s) == 1 else -0.40
    if s.startswith('.') and '\n' in s:
        return 0.32
    if word.isascii():
        if word.isalpha():
            if s.startswith(' '):
                return -0.21 if word[0].isupper() else -0.28
            return -0.40 if word[0].isupper() else -0.37
        return -0.12 if word.isdigit() else -0.21
    if HAN.search(word) or KANA.search(word):
        return -0.08
    return -0.27


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
    root = stem(s)
    value = 0.003
    if position == 0:
        value = opening(s)
    elif root.startswith('cust'):
        value = 0.12
    elif not s[:1].isspace() and s.lower().startswith('i'):
        if stem(previous).endswith('cust'):
            value = -0.95
        elif stem(previous).endswith('custom'):
            suffix = s.lower()
            if suffix in ('ized', 'ised'):
                value = -0.60
            elif suffix == 'izable':
                value = -0.25
    if s and not s.strip('·'):
        value = -0.46 if len(s) > 1 else 0.065
    if s == '\u0651':  # Arabic shadda: doubled-consonant mark.
        value = 0.22
    if position == 1 and previous.lower() == 'title' and s == ':':
        value = 1.08
    return (doc, position + 1, s), value

"""Investment spellings, with spillover to short 'st' word fragments.

Invest/vest pieces are positive, especially where a token completes the root
begun by the previous token. Investment nouns, investors, and Chinese investment
spellings also respond. Short st fragments have smaller spelling-dependent
responses, often negative after consonants and on following vowel endings.
A small baseline marks document starts; word state resets there. This is a
spelling approximation, not a general detector of financial topics.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()
ST_FRAGMENT = re.compile(r'(?:e|i|ge)?st(?:a|e|en|er|r|h|o|y|i)?\Z')


@lru_cache(maxsize=160000)
def romanize(text):
    return anyascii(text).lower().strip()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, word = ('', '') if first else carry[1:]
    t, p, old = romanize(text), romanize(previous), romanize(word)
    joined = bool(word and text and not text[0].isspace())
    value = 0.25 if first else 0.0

    # Ordinary investment forms, and roots left incomplete by tokenization.
    if re.fullmatch(r'invest(?:s|ed|ing|ments?|ors?)?', t):
        if 'ment' in t:
            value += 3.3 if t.endswith('s') else 4.4
        elif 'or' in t:
            value += 2.9 if t.endswith('s') else 3.7
        elif t.endswith('ed'):
            value += 5.2
        elif t.endswith('ing'):
            value += 5.5
        else:
            value += 6.9
    elif re.fullmatch(r'vest(?:s|ed|ing)?', t):
        value += 3.3
    elif t == 'investi':
        value += 1.6
    elif text.strip().lower() in ('inversión', 'inversiones'):
        value += 2.7
    if '投资' in text or '投資' in text:
        value += 2.4
    elif text.strip() == '投':
        value += 0.5

    if joined:
        if old.endswith(('invest', 'inwest')) and not t.startswith('ig'):
