    if word.startswith('.'):
        return -1.6 - 0.3 * (newlines == 1) - 3.0 * (newlines > 1)
    if word.startswith(';'):
        return -1.9 - 2.8 * bool(newlines)
    if word.startswith(':'):
        return -2.4 - 0.6 * bool(newlines)
    if word.startswith('{'):
