"""Component layers.1.mlp.down_proj:5797 - a document-opening token detector.

What it does: this component is silent everywhere except on the FIRST token of each
document (the first token of a packed row, or the first token after a document boundary).
There the model has no earlier context, so the component's output depends only on which
token it is. The program predicts a signed value from the token's kind:

  * bare line breaks ("\\n", "\\n\\n")                                -> strongly negative
  * text ending or starting with a line break                      -> negative
  * opening / closing brackets, braces                            -> strongly negative
  * commas, periods, colons, semicolons                           -> negative
  * digits 0-9                                                    -> positive
  * sentence-opening words (The, A, I, To, This, They, ...)       -> positive
  * common lowercase function words (of, is, for, by, are, ...)   -> mildly negative
  * " to"                                                         -> positive
  * everything else                                               -> 0

Everywhere else (every non-initial token) the component is near zero, so it predicts 0.
"""

READS = ()

SENTENCE_OPENERS = {
    "The", "A", "I", "To", "These", "They", "This", "In", "How", "What", "We", "It",
    "Into", "Their", "Our", "My", "Too", "Most", "Many", "Some", "Here", "There", "When",
    "If", "So", "You", "He", "She",
}
NEGATIVE_FUNCTION_WORDS = {
    "of", "is", "for", "by", "are", "be", "was", "were", "as", "can", "an", "or", "from",
    "on", "at", "not",
}


def token_value(s):
    core = s.strip()
    if s == "":
        return 0.0
    if "\n" in s or "\r" in s:
        return -5.5 if core == "" else -3.0
    if core and all(not c.isalnum() for c in core):
        if core[0] in "([{" or core[-1] in ")]}":
            return -3.5
        if core in {",", ":", ";", "."}:
            return -2.0
        return -0.5
    if core.isdigit():
        return 1.3
    if core in SENTENCE_OPENERS:
        return 1.9
    if s.startswith(" ") and core.lower() in NEGATIVE_FUNCTION_WORDS:
        return -1.5
    if s.startswith(" ") and core == "to":
        return 2.5
    return 0.0


def step(carry, prefix, upstream):
    t = prefix.position
    docs = prefix.document_ids
    is_doc_start = t == 0 or docs[t] != docs[t - 1]
    if not is_doc_start:
        return None, 0.0
    return None, float(token_value(prefix.token_strings[t]))

