"""A document-start pulse, with strength set by the kind of opening token.

It persists through identical repetitions of the opening token, then turns off.
Code declarations, articles and indentation have particularly strong pulses;
line breaks and forms of 'be' have little or no positive pulse. These coarse
classes approximate the substantially more token-specific native amplitudes.
"""
READS = ()

ARTICLES = {'a', 'an', 'the'}
IMPORTS = {'package', 'import', 'from'}
DEFINITIONS = set('const let var def function class struct interface enum '
                  'typedef int string'.split())
PREPOSITIONS = set('of in on at by for from with without into onto upon '
                   'over under above below between among through during '
                   'before after about against across around toward towards '
                   'behind beside beyond near out off'.split())
COPULAS = set('am is are was were be been being'.split())
PRONOUNS = set('I me my mine we us our ours you your yours he him his '
               'she her hers it its they them their theirs'.lower().split())


def opening_pulse(s):
    w = s.strip()
    low = w.lower()
    if s.startswith('<|'):
        return 3.1
    if '\n' in s or '\r' in s:
        return 0.0
    if not w:
        return 8.4 if len(s) == 1 else 13.4
    if w in IMPORTS and s == w:
        return 25.0
    if w in DEFINITIONS and s == w:
        return 17.5
    if w == 'using' and s == w:
        return 16.7
    if s.startswith('#') and len(s) > 1 and w.strip('#'):
        return 13.0
    if low in ARTICLES:
        return 11.4 if w.istitle() and s == w else 7.5
    if low == 'to':
        return 16.0 if w.istitle() else 11.7
    if low in COPULAS:
        return -0.7
    if low in PREPOSITIONS:
        return 5.2
    if low in PRONOUNS:
        return 2.6
    if w.isdigit():
        return 4.3
    if w in {'#', '//'}:
        return 8.3
    if w == ',':
        return 6.0
    if all(c == '·' for c in w):
        return 11.0
    if len(w) == 1 and w.isascii() and w.isalpha():
        return 4.5
    return 3.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        initial, value = token, opening_pulse(prefix.token_strings[-1])
    else:
        initial, value = carry[1], carry[2]
        if token != initial:
            value = 0.0
    return (doc, initial, value), value

