"""Document-start detector for layers.1.mlp.down_proj:5798.

What it does, in plain terms
----------------------------
The component is almost silent inside a document. Its activation is
concentrated on the FIRST token of each document: the token right after
<|endoftext|>, or the first token of a packed row. There the model has no
earlier text to look at, so the size of the activation is set by which word or
symbol opens the document:

  * code and markup openers fire hardest: `import`, `package`, `from`,
    `#include`, `def`, `const`, `using`, `class`, `int` ...
  * indentation runs and the words "The", "To", "A" fire strongly;
  * other function words (of, in, to, and, for ...) fire moderately;
  * punctuation and digits fire a little, ordinary words about the same;
  * auxiliary verbs and pronouns (is, was, be, it, I ...) sit near zero,
    and newlines are slightly negative.

Every other position predicts 0.
"""

READS = ()

IMPORT_WORDS = frozenset("import from package".split())
CODE_WORDS = frozenset(
    "def const using int class function var return public static void let print "
    "use new struct namespace #include #define #ifndef #!/ #from".split()
)
CAPITAL_FUNCTION_WORDS = frozenset("The To A".split())
FUNCTION_WORDS = frozenset(
    "the to of a an in for with on at by and or as that this from".split()
)
AUX_WORDS = frozenset(
    "is was be are were been am it I he He she She It they you so but not had has have".split()
)
PUNCTUATION = frozenset(",.:;=()[]{}#/*+-&|\"'%<>\\_~^`")


def first_token_value(text):
    """Activation predicted for a document's first token, given its text."""
    word = text.strip()
    if word == "":
        return -2.0 if "\n" in text else 9.5
    if word in IMPORT_WORDS and not text.startswith(" "):
        return 24.0
    if word in CODE_WORDS or text.lstrip() in CODE_WORDS:
        return 16.0
    if word in CAPITAL_FUNCTION_WORDS:
        return 11.0
    if word in FUNCTION_WORDS:
        return 7.5
    if word in AUX_WORDS:
        return 0.0
    if word and all(c in PUNCTUATION for c in word):
        return 5.0
    if word.isdigit():
        return 4.0
    return 3.5


def step(carry, prefix, upstream):
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return carry, 0.0
    return carry, float(first_token_value(prefix.token_strings[-1]))

