"""A sparse spelling-fragment detector.

The strongest responses are isolated 'ru' fragments (also Cyrillic ру), the
Thai letter ร and its immediate continuation, and a few compounds following
人 ('person'). Most ordinary words have no response. Token boundaries matter:
a short fragment is much stronger than the same letters inside a whole word.
Document-initial title and speaker labels are treated separately. Otherwise,
the first token of a document gets a small negative baseline.
"""

READS = ()

# Continuations of 人, grouped by the resulting compound's meaning.
PERSON_ENDINGS = (
    ('気气氣', 5.8),  # popularity
    ('手', 4.6),     # manpower
    ('教', 9.0),     # People's Education (textbooks)
    ('士', 6.0),     # person / scholar
    ('身', 4.2),     # person's body
    ('间間', 1.5),   # human world
    ('體体工', 2.0), # human body / artificial
    ('们們事', 1.6), # people / personnel affairs
    ('妻', 0.5),     # married woman
)


def predict(text, previous, position, older=""):
    if position == 1 and previous == 'Title' and text == ':':
        return 7.67
    if position == 0 and text == 'Person':
        return -3.0

    # Thai r and a few of its syllabic continuations.
    if text == 'ร':
        if previous == 'คน':  # Thai 'person'
            return 13.0
        if previous in ('การ', 'ความ'):  # nominalizing function words
            return 8.5
        return 4.4
    if previous.endswith('ร'):
        if text == 'ั':
            return 4.0 if previous == 'ร' else 2.5
        if text == 'ิ':
            return 1.4
        if previous == 'ร':
            if text in ('ับ', '่ว', 'ุ'):
                return 5.3
            if text == 'ู':
                return 3.5
            if text == 'ู้':
                return 2.4
    if text == 'ส':
        syllable = older + previous
        if syllable.endswith('รู้'):
            return 8.0
        if syllable.endswith('รี'):
            return 4.7
        if previous.endswith('ร'):
            return 5.0

    if previous.endswith('人'):
        for endings, strength in PERSON_ENDINGS:
            if len(text) == 1 and text in endings:
                return strength
        if text == '気が':
            return 1.5

    if text == '人':
        return 0.3
    if text in ('人气', '人氣', '人事'):
        return 1.4

    # Latin ru fragments, including domain names and code namespaces.
    if text == '.ru':
        return 5.7
    fragment = text.strip()
    if fragment.lower() == 'ru':
        if text.startswith(' '):
            if previous.strip() in ('import', 'package'):
                return 6.5 if previous.strip() == 'import' else 10.2
            if fragment.isupper():
                return 4.0
            return 3.0 if fragment.islower() else 2.2
        if fragment != 'ru':
            return 3.0
        stem = previous.strip().lstrip('-_')
        if stem == 'l':  # the LRU (least-recently-used) abbreviation
            return 6.2
        if previous and not previous[-1].isalnum():
            return 3.2
        if previous[-1:].lower() in ('t', 'k', 'd', 'p', 'g', 'c', 'r'):
            return 0.4
        return 1.8
    if text in ('aru', 'uru', 'oru'):
        return {'aru': 0.8, 'uru': 2.1, 'oru': 0.4}[text]

    # Letter pairs split across two tokens.
    if previous and text and previous[-1] in 'rRрР':
        if text == 'ъ':
            return 2.5 if previous.strip() == 'р' else 0.0
        if text in ('u', 'U', 'у', 'У'):
            if previous == '.R':
                return 8.4
            if previous.strip().lower() in ('r', 'р'):
                return 5.8 if text == 'У' else 3.5
            if previous[-1] in 'RР':
                return 4.0
            if previous[-1] == 'р':
                return 0.2
            if previous[-2:-1].lower() in 'ou':
                return 1.2
            if previous[-2:-1].lower() in 'ir':
                return 4.0
            # An r in a consonant cluster is a weaker trigger.
            if previous[-2:-1].lower() in 'bcdfghjklmnpqrstvwxyz':
                return 0.5
            return 2.6
        if text.startswith('у') and len(text) <= 2:
            return 1.5
        if text.lower() in ('us', 'uv', 'uk'):
            return 0.8
        if text[0] == 'u' and len(text) <= 3:
            return 0.15
    if fragment == 'ру':
        return 0.4
    return -0.25 if position == 0 else 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, older, position = '', '', 0
    else:
        _, previous, older, position = carry
    text = prefix.token_strings[-1]
    value = predict(text, previous, position, older)
    return (document, text, previous, position + 1), float(value)

programs.haiku:
"""layers.1.mlp.down_proj : component 5802, as a short rule set over the current token.

What the component does, in plain terms: it is a sparse "r/u-sound" detector. It is
silent on almost every token, but it fires on

- the Latin / Cyrillic syllable "ru" as a whole token (" ru", "ru", " Ru", ".ru", "ру", "ус"),
  the most frequent strong trigger;
- the Thai letter "ร" (r), which is the largest single response;
- the bare letter "u" or "у" (Sumer-u, Yuer-u, "RU" pieces), weakly;
- the Chinese/Japanese "popularity" compound 人気 / 人气 (the second character, 気/气/氣);
- the colon in a "Title:" label that opens a document;
- the first token of every document, where it is mildly negative on average (the real value
  there depends on which token it is; this program predicts one constant for all of them).

Everything else is predicted as 0. On the eval rows this captures about an eighth of the
variance (r = 0.36) and about half of the effect that switching the component off has on
the model's next-token distribution: most of the component's activity is small,
token-specific and not described by a short list.

Main program: `step` looks at the newest token (and the one before, for "Title" + ":"),
and resets at a document boundary. No carry is needed.
"""

READS = ()

RU_TOKENS = {"ru", ".ru", "ру", "ус", "rus", "uru", "aru"}
U_LETTERS = {"u", "у"}
KI_CHARS = {"気", "气", "氣"}
THAI_R = {"ร"}

DOC_START = -0.235   # first token of a document
TITLE_COLON = 1.97   # ":" right after "Title"
RU = 1.07            # "ru"-family syllable token
THAI_R_VALUE = 4.6   # Thai letter ร
KI = 0.73            # 気 / 气 / 氣
U_LETTER = 0.07      # bare u / у


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip().lower()
    t = prefix.position
    new_doc = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        return carry, DOC_START
    prev = prefix.token_strings[-2].strip() if t >= 1 else ""
    if tok == ":" and prev == "Title":
        return carry, TITLE_COLON
    if tok in RU_TOKENS:
        return carry, RU
    if tok in THAI_R:
        return carry, THAI_R_VALUE
    if tok in KI_CHARS:
        return carry, KI
    if tok in U_LETTERS:
        return carry, U_LETTER
    return carry, 0.0

programs.sol:
"""Approximate startup responses to document boundaries and formatting.

The large responses are concentrated at the beginning of documents.  This
models end markers, opening layout punctuation and tokens used in C/C++
code, as well as the opening article 'the', negation 'not', and a 'Title:'
label. Away from startup it predicts a small negative value for backtick
delimiters and leaves most other activity at zero. Document changes reset
state. These rules capture selected patterns, not the full lexical response.
"""
READS = ()

# Opening layout and syntax markers, not ordinary words.
OPENING_MARKERS = {
    '<|endoftext|>': -9.5,
    '<|im_start|>': -0.37,
    '---\n': -4.06,
    '|': -1.81,
    '|\n': -1.81,
    '@': -2.68,
    ' .': 2.45,
    ' ,': 1.07,
    '\t': 0.77,
}


CODE_TYPES = {
    'int': 1.8,
    'bool': 1.94,
    'string': 3.1,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, first = 0, token
    else:
        age, first = carry[1] + 1, carry[2]

    stripped = token.strip()
    value = -0.075 if stripped and set(stripped) == {'`'} else 0.0
    if age == 0:
        value = OPENING_MARKERS.get(token, -0.08)
        if token == '#pragma':
            value = -4.37
        elif token == '#ifndef':
            value = 2.32
        elif token.startswith('#!'):
            value = -1.32
        elif token in CODE_TYPES:
            value = CODE_TYPES[token]
        elif token == 'Title':
            value = 0.84
        elif stripped.lower() == 'the':
            value = 0.50
        elif stripped.lower() == 'not':
            value = -0.70
    elif age == 1 and first == 'Title' and token == ':':
        value = -5.0
    elif age == 1 and first == '#pragma' and token == ' once':
        value = 1.08
    elif token == '<|endoftext|>':
        value = 0.066 - 2.03 / age ** 0.75

    return (doc, age, first), value

"""Negative spelling pulses, chiefly on isolated Thai ส and ย and some
following vowel, tone and sonorant fragments. Separate rules recognize Greek
sy-, Cyrillic s-hard-sign, and Vietnamese suy in diacritic-bearing context.
Other positions get zero. These spellings need not share a meaning.
"""
import unicodedata

READS = ()
# Thai vowel/tonal signs, and the consonants completing Greek sy- prefixes.
THAI_SIGNS = {
    'ั': -8.2, 'า': -2.5, 'ิ': -6.6, 'ี': -4.4,
    'ึ': -2.9, 'ื': -4.2, 'ุ': -2.5, 'ู': -9.0,
    '่': -4.4, '้': -4.0, '์': -1.0,
}
GREEK = {'ν': -6.2, 'γ': -4.2, 'μ': -1.8, 'σ': -2.4}
SONORANTS = set('งญณนมยรลวฬ')
FINAL_STOPS = set('กคขตดทถบป')
# Dot below, hook above, horn, breve, and crossed d.
VIETNAMESE_MARKS = '\u0323\u0309\u031b\u0306đ'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = b'' if carry is None or carry[0] != doc else carry[1]
    h = old.decode('utf-8', errors='ignore')
    token = prefix.token_strings[-1]
    s = token.strip()
    value = 0.0
    if s == 'ส':
        value = -3.5 if token.startswith(' ') else -7.7
    elif s == 'ย':
        value = -3.0
    elif s and h.endswith('ส') and s[0] in THAI_SIGNS:
        value = THAI_SIGNS[s[0]]
        if len(s) > 1:
            value += 5.3 if s[0] == 'ั' else 0.0
            value += 3.4 if s[0] in 'ีูื' else 0.0
            if s[0] == 'ิ' and s[-1] in FINAL_STOPS:
                value += 4.3
    elif s and h.endswith(('สิ', 'สั')) and s[0] in '่้':
        value = -6.3
    elif (h.endswith(('สิ่', 'สิ้', 'สั่', 'สั้', 'สิ', 'สั'))
          and s in SONORANTS):
        value = -4.8
    elif h.endswith('สู') and s == 'ง':
        value = -5.5
    elif s == 'อม' and h.endswith(('ื่', '่')):
        value = -5.3
    elif h.endswith(('σ', 'Σ')) and s == 'υ':
        value = -1.5
    elif h.endswith(('συ', 'Συ')):
        value = GREEK.get(s, 0.0)
    elif s == 'ъ' and h.endswith(('с', 'С')):
        value = -1.6 if len(h) < 2 or not h[-2].isalpha() else -0.4
    elif token == s and ((s == 'y' and h.lower().endswith('su')) or
                         (s == 'uy' and h.lower().endswith('s'))):
        if any(c in unicodedata.normalize('NFD', h) for c in VIETNAMESE_MARKS):
            value = -9.2
    return (doc, (old + prefix.token_bytes[-1])[-320:]), value

"""Predict separators, especially after an opening heading-like line.

Capitalized, Markdown and short Han opening lines get larger break values.
Later plain lines and chat/tool boundaries have smaller separator values.
The initial Title: colon is unusually strong. Doubled backslashes are positive
in escaped text but negative near LaTeX commands; initial tabs are positive.
Other tokens stay near zero. State resets at each document boundary.
"""
import regex as re

READS = ()


def opening_break(text, row_start, double):
    # Capitalized opening lines and Markdown headings resemble document titles.
    if text.startswith('Title:'):
        return 0.25
    if text == 'Question':
        return 0.75
    heading = re.match(r'^(#{1,6})\s+', text)
    if heading:
        strength = 2.2 if len(text) < 19 else 3.7
        if len(heading[1]) == 1:
            return strength
        return 1.5 if len(heading[1]) == 2 else 0.1
    if (len(text) < 100 and not text[:1].isspace()
            and re.search(r'\p{Script=Han}', text[:8])):
        return 2.0 if double else 1.5
    if text[:1].isupper():
        if double:
            return 2.4 if len(text) < 25 else 4.1
        words = re.findall(r'[^\W\d_]+', text)
        return 1.6 if len(words) < 22 else 0.12
    return 0.1 if row_start else 0.46


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = int(prefix.document_ids[-1])
    if carry is None or doc != carry[0]:
        pos, lines, parts, previous, recent = 0, 0, [], '', ''
        row_start = prefix.position == 0
    else:
        _, pos, lines, parts, previous, row_start, recent = carry

    value = -0.003
    if pos == 0 and token in ('\t', '\\t'):
        value = 1.6
    elif pos == 0 and token == 'Title':
        value = -1.74
    elif pos == 1 and previous == 'Title' and token == ':':
        value = 14.34
    elif token.endswith('\\\\'):
        latex = re.search(
            r'\\(?:frac|lim|begin|end|left|right|hat|vec|text|color|overline|pmatrix)\b',
            recent,
        )
        value = -1.2 if latex else 0.69
    elif '\n' in token:
        bare = token.strip('\r\n') == ''
        double = token.count('\n') >= 2
        text = ''.join(parts) + token.split('\n')[0]
        heading = re.match(r'^(#{1,6})\s+', text)
        value = -0.02
        if bare:
            if lines == 0:
                value = opening_break(text, row_start, double)
            elif heading:
                value = 0.2 if len(heading[1]) == 1 else 0.1
            else:
                if double:
                    value = 0.26 if lines < 3 else 0.04
                else:
                    value = 0.15 if lines == 1 else 0.033
            if previous == '<|im_end|>':
                value = 0.29 if lines == 0 else 0.34
                if '</tool_response>' in recent[-100:]:
                    value = 0.52
            elif previous == 'user':
                value = 0.34 if lines == 0 else 0.43
            elif previous == 'assistant':
                value = 0.55 if '</tool_response>' in recent[-100:] else 0.14
            elif previous in ('<think>', '</think>'):
                value = 0.4
        elif lines == 0 and double and token.strip('\r\n') == ';':
            value = 0.62
        elif (lines == 0
              and token.strip('\r\n') in ('?', ')', '…', '”', '"')):
            value = opening_break(text, row_start, double)
            if token.startswith('?'):
                value = 0.65 * opening_break(text, row_start, False)

    if '\n' in token:
        parts = [token.rsplit('\n', 1)[-1]]
    else:
        parts.append(token)
    lines += token.count('\n')
    recent = (recent + token)[-160:]
    carry = (doc, pos + 1, lines, parts, token, row_start, recent)
    return carry, float(value)

programs.haiku:
"""Candidate 3: title-line newline only.

The component fires on the newline that ends a document's opening title line
(a short, capitalised line with no final punctuation, right after <|endoftext|>).
Everywhere else it predicts 0.
"""
READS = ()


def _is_title(line):
    s = line.strip()
    words = s.split()
    if not words or not (s[0].isupper() or s[0] == "#"):
        return False
    if s.endswith((".", ",", ";", "?", "!", ")")):
        return False
    return len(words) <= 18


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if carry is None or prefix.document_ids[-1] != prefix.document_ids[-2]:
        line, seen = "", False
    else:
        line, seen = carry
    value = 0.0
    if not seen and "\n" in tok:
        if _is_title(line):
            value = 3.0 if tok == "\n\n" else 1.3
        seen = True
    elif not seen:
        line += tok
    return (line, seen), value

programs.sol:
"""Pulse on the completing digit of a plausible calendar year.

Years in the late twentieth and early twenty-first centuries are strongest.
Temporal prepositions and full month names strengthen the pulse. Attachment
to preceding text, long digit strings, abbreviated months, and round century
numbers weaken it. Fullwidth years receive a smaller pulse.
An additional distinct response marks a document-initial 'Title:' header.
"""
import re
from atoms import FULLWIDTH_DIGITS

READS = ()
MONTHS = set('january february march april may june july august '
             'september october november december'.split())
SHORT_MONTHS = set('jan feb mar apr jun jul aug sep sept oct nov dec'.split())
TIME_PREPOSITIONS = set('in since from during until by before after'.split())


def year_strength(year):
    if not 1400 <= year < 2100:
        return 0.0
    if year < 1600:
        return 0.2
    if year < 1730:
        return 0.7
    if year < 1800:
        return 1.3
    if year < 1900:
        return 2.1
    if year < 1910:
        return 1.9
    if year < 1930:
        return 2.4
    if year < 1970:
        return 3.3
    if year < 2011:
        return 4.1
    return max(1.0, 4.2 - 0.10 * (year - 2010))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, digits, before = carry
    token = prefix.token_strings[-1]
    fullwidth = token in FULLWIDTH_DIGITS
    value = 0.0
    if len(token) == 1 and (token in '0123456789' or fullwidth):
        digits += str(int(token))
        if len(digits) >= 4:
            year = int(digits[-4:])
            value = year_strength(year)
            word = re.search(r'(\w+|[^\w\s])\s*$', before)
            word = word[1].lower() if word else ''
            scale = 0.97
            if word in TIME_PREPOSITIONS or word == 'the':
                scale += 0.22
            if word in MONTHS:
                scale += 0.13
            if word in SHORT_MONTHS:
                scale -= 0.12
            if before and not before[-1].isspace() and before[-1] not in '([':
                scale -= 0.24
            if len(digits) > 4:
                scale -= 0.52
            if year % 100 == 0:
                scale *= 0.5
            if fullwidth:
                scale *= 0.65
            value *= max(0.0, scale)
    else:
        if token == ':' and before == 'Title':
            value = 16.0
        before = (before + digits + token)[-100:]
        digits = ''
    return (doc, digits, before), value

"""Document-opening surface-form response.

The response is concentrated on the first token (and an unchanged repeated
opening token). Consonant letters tend positive, uppercase vowels negative;
punctuation and very common words are weaker or negative. Script, spacing,
and broad programming-keyword classes refine the estimate. Later tokens are
approximated by zero; idiosyncratic lexical variation is not modeled.
"""
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
DEPENDENCY_IMPORTS = {'import', 'using', '#include'}
MODULE_DECLARATIONS = {'package', 'module', 'export'}
DECLARATION_MODIFIERS = {'public', 'private', 'protected', 'static', 'extern'}
INTERROGATIVES = {
    'who', 'whom', 'whose', 'what', 'which', 'when', 'where', 'why', 'how'
}
ALPHABETIC_SCRIPTS = regex.compile(
    r'^[\p{Script=Latin}\p{Script=Cyrillic}\p{Script=Greek}]$'
)
LATIN = regex.compile(r'\p{Script=Latin}')
HAN = regex.compile(r'\p{Script=Han}')
ARABIC = regex.compile(r'\p{Script=Arabic}')
CYRILLIC = regex.compile(r'\p{Script=Cyrillic}')


@lru_cache(maxsize=16000)
def opening_response(text):
    t = text.strip()
    if t.startswith('<|'):
        return 0.64
    if not t:
        return -0.05 if '\n' in text else -0.9
    if t.isdigit():
        return -0.6
    spaced = text[0].isspace()
    if t in DEPENDENCY_IMPORTS:
        return 1.6 if spaced else 4.7
    if t in MODULE_DECLARATIONS:
        return -0.7 if spaced else -3.0
    if t in DECLARATION_MODIFIERS:
        return 4.2 if spaced else 6.5
    if t.lower() in INTERROGATIVES:
        return -0.3 if spaced else -2.0
    letters = [c for c in t if c.isalpha()]
    if not letters:
        if '\ufffd' in t:
            return 2.1
        if t[0] == '#':
            return -2.9
        if t[0] in '([{':
            return -1.8
        if t[0] == ':':
            return 0.0
        return -1.1
    if len(t) == 1 and ALPHABETIC_SCRIPTS.fullmatch(t):
        vowel = anyascii(t).lower() in 'aeiou'
        if vowel:
            if not t.isascii():
                return -7.2 if t.isupper() else -2.6
            if t.isupper():
                frequency = zipf_frequency(t, 'en')
                return -1.3 if frequency >= 6 else -4.3
            return -0.6 if spaced else 1.2
        value = 4.6 - 1.1 * spaced
        if not t.isascii():
            value += 1.0 if t.isupper() else -1.0
        return value
    if all(LATIN.match(c) for c in letters):
        low = t.lower()
        frequency = zipf_frequency(low, 'en')
        vowel_fraction = sum(c in 'aeiou' for c in low) / len(letters)
        return (2.1 - 4.5 * vowel_fraction
                - max(0.0, frequency - 5.0)
                + 0.5 * (len(letters) <= 3)
                + 0.8 * t.istitle()
                + 0.55 * spaced
                + 0.8 * (low[0] in 'aeiou'))
    if any(HAN.match(c) for c in letters):
        return 1.6
    if any(ARABIC.match(c) for c in letters):
        return 5.0
    if any(CYRILLIC.match(c) for c in letters):
        return 2.3
    return 2.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True)
    elif carry[2] and token != carry[1]:
        carry = (doc, carry[1], False)
    value = opening_response(prefix.token_strings[-1]) if carry[2] else 0.0
    return carry, value

programs.haiku:
"""Layer-1 MLP down-projection component 5808: a document-start detector.

What it does: this component is almost silent everywhere except on the first token of a
document (the first token of a row, or the first token after a document break inside a
packed row). There the model has no earlier context, so the component's activation is a
fixed function of that single token's identity. Its sign and size follow broad kinds of
token:

  * a single plain letter, or a short capitalised fragment: strongly positive (about +3)
  * other scripts (Cyrillic, Arabic, CJK, Thai, ...): positive (about +2)
  * ordinary word starts and word fragments: mildly positive (about +1.2; +0.6 if a word
    mixes accented and plain letters)
  * tokens made only of accented Latin letters (ä, ö, ł, ę, é ...): negative (about -4)
  * punctuation, code symbols, whitespace, digits: negative (about -1)
  * common English function words (the, of, and, is ...): near zero (about -0.5)

Everywhere else (every position after the first token of a document) it predicts 0.
"""

import unicodedata

READS = ()

FUNCTION_WORDS = frozenset(
    "the a an of and to in is for that with on as be are by was or from at it this not "
    "i you he she we they his her its their".split()
)


def _accented_latin(c):
    return ord(c) > 127 and "LATIN" in unicodedata.name(c, "")


def _doc_start_value(s):
    core = s.strip()
    letters = [c for c in core if c.isalpha()]
    if not core:
        return -0.6
    if not letters:
        return -0.6 if core.isdigit() else -1.1
