        return -0.5
    if len(core) == 1:
        return 3.9
    if len(core) <= 2 and core[0].isupper():
        return 2.8
    return 1.15


def step(carry, prefix, upstream):
    ids = prefix.document_ids
    starts_document = prefix.position == 0 or ids[-1] != ids[-2]
    if not starts_document:
        return None, 0.0
