"""A coarse foreign-spelling /f/ detector, not a word-meaning detector.

The main negative response is to short f-bearing fragments and the fragment
immediately after them. Romanization lets the same rule see ф, ف and フ.
Recent completed words supply a non-English language gate; short i/t versus
y/h fragments supply smaller spelling corrections. There are separate rules
for document-opening title/comment syntax and repeated middle dots.
"""
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency
import regex

READS = ()
LANGUAGES = ('en', 'de', 'fr', 'es', 'it', 'pt', 'ro', 'pl',
             'tr', 'hu', 'ru', 'uk', 'ar', 'fa', 'id')
IDEOGRAPHS = regex.compile(r'[\p{Han}\p{Hangul}]')
F_SCRIPTS = regex.compile(r'[\p{Cyrillic}\p{Arabic}\p{Katakana}]')


@lru_cache(maxsize=60000)
def word_evidence(word):
    if not 2 <= len(word) <= 40:
        return None
    return tuple(max(0.0, zipf_frequency(word, lang) - 3.0)
                 for lang in LANGUAGES)


@lru_cache(maxsize=60000)
def spelling(s):
    raw = s.strip()
    # A Han character's transliteration is not an alphabetic fragment.
    roman = '' if IDEOGRAPHS.search(raw) else anyascii(raw).lower()
    letters = ''.join(c for c in roman if 'a' <= c <= 'z')
    short = 1 <= len(letters) <= 4
    has_f = 'f' in letters
    script_f = has_f and bool(F_SCRIPTS.search(raw))
    english = zipf_frequency(raw.lower(), 'en')
    return letters, short, has_f, script_f, english


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, word, context, previous = 0, '', (0.0,) * len(LANGUAGES), ''
    else:
        _, pos, word, context, previous = carry
    s = prefix.token_strings[-1]
    joined = bool(word) and s[:1].isalpha()

    # Update language evidence only when a word is complete.
    for ch in s:
        if ch.isalpha():
            word += ch
        elif word:
            evidence = word_evidence(word.lower())
            if evidence is not None:
                context = tuple(.85 * old + .15 * new
                                for old, new in zip(context, evidence))
            word = ''
    gap = max(context[3:]) - max(context[:3])
    foreign = min(1.0, max(0.0, (gap - .2) / .4))

    letters, short, has_f, script_f, english = spelling(s)
    fragment = short and has_f and (english < 4.5 or joined or len(letters) == 1)
    value = 0.0
    if script_f and short:
        value -= .30
    elif has_f:
        value -= foreign * (.04 + .50 * fragment + .04 * fragment * joined)

    old_letters, old_short, old_f, old_script, _ = spelling(previous)
    if joined and old_short and old_f:
        if old_script:
            value -= .30
        else:
            value -= foreign * (.075 + .26 * (len(old_letters) == 1))
    if short:
        value += foreign * (-.04 * ('i' in letters) - .05 * ('t' in letters)
                            + .03 * ('y' in letters) + .02 * ('h' in letters))

    # Highly stereotyped document openings have large, distinct responses.
    if pos == 0 and s == 'Title':
        value = -.317
    elif pos == 1 and previous == 'Title' and s == ':':
        value = 4.209
    elif pos == 0 and s == '//\n':
        value = -3.949
    elif len(s) >= 2 and set(s) == {'·'}:
        value = 1.054

    return (doc, pos + 1, word, context, s), float(value)

