programs.haiku:
"""Program: a token that sets up a computed result, inside arithmetic context.

What the component does: it goes negative on the word or symbol that introduces a
derived value or a conclusion in a worked calculation: the equals sign, the arrows
⇒ → => ≈, and so / thus / therefore / hence. The strongest cases are right after a
numeric expression ("18*(0.5) =", "x = 2, so"), where the next thing written is a
computed result. The same words in ordinary prose are weakly negative, and most
other tokens are near zero. A bare space that follows "=", "is", "to" or ":" in
arithmetic is mildly negative, since the number that comes next is the result.

"Arithmetic context" is how many digits appear in the last 20 characters of the
same document (at least 3 means arithmetic). The response grows with the digit
count, up to 8 digits. All the values are hand-set, not fitted to a table.
"""
READS = ()

ARROWS = {"⇒", "→", "=>", "≈"}
CONCLUDE = {"so", "thus", "therefore", "hence", "implies", "suggests", "gives", "means"}
EQUALS = {"=", ")="}
COPULA = {"is", "would", "which"}
SETUP = {"=", "is", "to", ":", "≈"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    same = [t for t, d in zip(toks[-20:], docs[-20:]) if d == docs[-1]]
    word = toks[-1].strip().lower()
    prev = toks[-2].strip() if len(toks) > 1 and docs[-2] == docs[-1] else ""
    after_number = prev[-1:].isdigit() or prev.endswith(")")
    digits = sum(ch.isdigit() for ch in "".join(same))
    math = digits >= 3
    value = 0.0
    if word in ARROWS:
        value = -3.0 if math and after_number else (-2.0 if math else -0.2)
    elif word in EQUALS:
        value = -3.3 if math and after_number else (-0.8 if math else -0.1)
    elif word in CONCLUDE:
        value = -2.7 if math else -0.9
    elif word in COPULA:
        value = -0.5 if math else 0.0
    elif word == "" and prev in SETUP and math:
        value = -0.8
    if math:
        value *= min(digits, 8) / 6.0
    return carry, float(value)

