"""A spelling heuristic, strongest on 'goal(s)' and repeated g syllables.

Short spellings such as gig, goog and gorg, including ones split between
tokens, give positive responses. Familiar whole words weaken the latter
signal. Alphabetic scripts are transliterated; repeated g-sounding kana
are handled separately. Girl(s) is mildly positive, and gee is negative.
This is only a partial account of the component's lexical responses.
"""
import codecs
import re
from functools import lru_cache

import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
ALPHABET = regex.compile(r'[\p{Latin}\p{Cyrillic}\p{Greek}\p{Arabic}]')
G_SYLLABLE = r'g[rl]?[aeiou]{1,2}[rl]?g'


@lru_cache(maxsize=32768)
def letters(text):
    # Do not concatenate the many romanized syllables of a CJK sentence.
    cleaned = ''.join(ch if not ch.isalpha() or ALPHABET.fullmatch(ch)
                      else ' ' for ch in text)
    return anyascii(cleaned).lower().replace('gh', 'g')


@lru_cache(maxsize=32768)
def familiarity(word):
    return min(1., max(0., (zipf_frequency(word, 'en') - 2.) / 4.))


def first_word(text):
    match = re.search('[a-z]+', text)
    return match[0] if match else ''


def predict(text, history):
    t, h = letters(text), letters(history)
    current = first_word(t)
    match = re.search('[a-z]+$', h)
    before = match[0] if match else ''
    joined = bool(t and h and t[0].isalpha() and h[-1].isalpha())
    match = re.match('[a-z]+', t)
    first = match[0] if match else ''
    word = before + first if joined else current
    value = 0.

    if word.startswith('goal'):
        value += 5.6
        if word == 'goals':
            value -= 1.
        elif word != 'goal':
            value -= 4.2
        if '--' in history[-8:]:
            value += 3.4
    sound = anyascii(text).strip().lower()
