            if re.match('[aeiouy]{1,2}l', first):
                value += 3.6
        if before.endswith('g') and not before.endswith('ng'):
            if first.startswith('o'):
                value += .35
            if before == 'g' and vowel:
                value += .33
        if 'g' in before[-4:] and len(first) <= 4 and 'g' in first:
            value += .5 + (1.1 if text.isupper() else 0.)
    else:
