        base, single, long, e_bonus = JOINS[pair]
        value += base + single*(len(s) == 1) + long*(len(s) > 3)
        value += e_bonus*(len(q) > 1 and q[-2] in 'eе')
        if pair == 'rb' and z.startswith('be'):
            value += 1.27
        if pair == 'rv' and z[1:2] in ('a', 'e', 'i', 'o', 'u'):
            value += 1.07
