            value += 1.06 + 1.71*previous.isupper() - 0.19*(len(s) > 3)
        elif q.endswith('rb'):
            value += 0.18
        old_pair = joined(previous, earlier)
        if len(previous) == 1:
            value += {'rv': 1.8, 'рв': 0.9, 'rb': 0.4, 'rw': 0.4}.get(old_pair, 0)
    return (doc, s, previous), float(value)

