    'do': 0.3, 'put': 0.65, 'carry': 0.45, 'give': 0.2,
    'such': 1.0, 'quite': 2.2, 'many': 0.6,
}
OBJECTS = {
    'take': {
        'part': 5.3, 'hold': 3.7, 'note': 4.5, 'notice': 5.5,
        'care': 1.4, 'place': 0.65, 'effect': 0.65,
        'action': 1.7, 'shape': 2.5, 'office': 2.8,
    },
    'make': {
        'use': 2.4, 'fun': 5.2, 'sure': 0.15, 'sense': 0.3,
    },
    'keep': {'track': 6.3, 'quiet': 3.8, 'pace': 1.1},
    'have': {'fun': 3.6},
    'let': {'go': 4.7},
    'poke': {'fun': 4.7},
}
VERBS = set(LIGHT_VERBS) | set(OBJECTS)
for group in PARTICLES.values():
    VERBS.update(group)


@lru_cache(maxsize=16384)
def noun_context(word):
    possessives = {
        'my', 'your', 'his', 'her', 'our', 'their', 'its', "'s", '’s',
    }
    return (word in possessives or word in {'a', 'an', 'the'}
            or 'adjective' in wordnet.parts_of_speech(word))


@lru_cache(maxsize=16384)
def lemma(word):
    if word in VERBS:
        return word
    for base in wordnet.base_forms(word):
        if base in VERBS:
            return base
    return word


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    if start:
        previous = earlier = previous_raw = ''
        recent_math = age = 0
    else:
        _, previous, earlier, previous_raw, recent_math, age = carry
    base = lemma(previous)
    boundary = start or raw[:1].isspace() or previous_raw[-1:].isspace()

    if word in PARTICLES:
        value = -PARTICLES[word].get(base, 0.0)
        if word == 'on':
            if previous == 'take' and noun_context(earlier):
                value = -2.1
            elif base == 'hold' and noun_context(earlier):
                value *= 0.5
            weak_forms = {
                'held', 'holding', 'kept', 'carried', 'hung', 'hanging',
            }
            if previous in weak_forms:
                value *= 0.55
            elif previous in {'going', 'reading', 'caught'}:
                value *= 0.65
        if previous == 'taken':
            value *= 0.3
        elif word == 'up' and previous in {'kept', 'caught'}:
            value *= 0.7
    elif word in {'a', 'an'}:
        value = -LIGHT_VERBS.get(base, 0.0)
        if previous == 'made':
            value *= 0.55
        if word == 'an':
            if base == 'keep':
                value *= 1.65
            elif base == 'take' and previous != 'took':
                value *= 0.45
    else:
        value = -OBJECTS.get(base, {}).get(word, 0.0)
    if previous == 'took':
        value *= 1.2
    if not boundary:
        value = 0.0

    # Habitual 'used to' differs from passive 'is used to'.
    if word == 'to' and previous == 'used':
        if earlier in {'be', 'is', 'are', 'was', 'were', 'been', 'being'}:
            value = 0.1
        else:
            pronoun = earlier in {'i', 'we', 'you', 'he', 'she', 'it', 'they'}
            value = -2.4 if pronoun else -0.65

    # Educational worksheets, particularly headings and mathematical tasks.
    if word in {'worksheet', 'worksheets'} and boundary:
        singular = word == 'worksheet'
        value = 3.0 if singular else 1.5
        if raw.strip()[0].isupper():
            value += 3.5 if singular else 1.2
        if recent_math:
            value += 2.0 if singular else 0.5
        if previous == 'math':
            value += 6.0 if singular else 0.5
        elif previous in {'the', 'a', 'one', 'this'}:
            value *= 0.5
    if raw == '_on':
        value = -0.6
    elif raw == '-on' and base == 'carry':
        value = -3.5
    if word == ':' and previous == 'title' and age == 1:
        value = -3.45
    if start and not word.startswith('worksheet'):
        value = 0.2 if word.isalpha() and not raw.isupper() else 0.03

    recent_math = (8 if word in {'math', 'mathematics', 'arithmetic'}
                   else max(0, recent_math - 1))
    join_word = raw.isalpha() and previous.isalpha() and not boundary
    current = previous + word if join_word else word
    return (doc, current, previous, raw, recent_math, age + 1), float(value)

"""A narrow approximation of procedural 'until', strongest in recipes.

Recent food-preparation words strengthen the negative 'until' response;
mixing and 'or until' strengthen it further. Knitting and repetition have
smaller effects. Negation and capitalization weaken it, and 'till' gets a
weaker contextual response. All other tokens get zero. History is bounded
and reset at document boundaries. Chinese lexical responses and weak
background activations are deliberately left unmodeled.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
MIXING = set('mix stir whisk beat blend knead fold combine'.split())
HEATING = set('cook bake fry boil simmer roast saute sauté melt grill'.split())
PREPARING = set(
    'pulse process rise roll grind soak rinse whip sweat cool chill'.split()
)
CRAFT = set('knit crochet sew stitch'.split())
REPEAT = set('repeat iterate loop rewatch retry'.split())

@lru_cache(maxsize=8192)
def roots(word):
    return set(wordnet.base_forms(word)) | {word}

@lru_cache(maxsize=8192)
def food(word):
    return 'noun.food' in wordnet.categories(word)


def until_value(before, token):
    words = re.findall(r"[^\W\d_]+", before.lower())
    recent = [roots(w) for w in words[-20:]]
    nearby = set().union(*recent) if recent else set()
    kitchen = any(food(w) for w in words[-40:])
    mix = bool(nearby & MIXING) and (
        kitchen or bool(nearby & {'stir', 'whisk', 'knead'}))
    hot = bool(nearby & HEATING) or ('heat' in nearby and kitchen)
    process_food = kitchen and bool(nearby & PREPARING)
    if 'rise' in nearby and not (nearby & (PREPARING - {'rise'})):
        process_food = bool(set(words[-40:]) & {'dough', 'yeast'})
    cooking = mix or hot or process_food
    repeat = bool(nearby & REPEAT)
    negated = bool(re.search(r"\b(not|never|wasn.t|didn.t|wouldn.t|won.t)\b",
                             before[-90:].lower()))
    value = -0.78
    if cooking:
        value -= 5.25
    if mix:
        value -= 1.07
    if cooking and words and words[-1] == 'or':
        value -= 3.59
    if nearby & CRAFT:
        value -= 1.68
    if repeat:
        value -= 0.85
    if negated:
        value += 0.71
    if token[:1].isupper():
        value += 0.77
    if token.lower() == 'till':
        value = 0.7 * (value + 0.78)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else b''
    token = prefix.token_strings[-1].strip()
    value = 0.0
    if token.lower() in {'until', 'till'}:
        value = until_value(history.decode('utf8', 'ignore'), token)
    history = (history + prefix.token_bytes[-1])[-600:]
    return (doc, history), float(value)

"""Approximate a word-continuation feature, especially after sh.

Short vowel-led pieces after sh receive positive values, strongest for
nasal syllables such as sh-eng, sh-ang and sh-un. The th digraph has a
narrower, weaker response; a transliterated sh has a reduced response. A few document-opening punctuation
patterns have a separate negative response, as do CJK forum/registration
words and Japanese lecture endings. Single letters, articles and underscored
identifiers also receive negative estimates at a document opening. Ordinary
text stays near zero.
"""
import re
import unicodedata
from opencc import OpenCC
from anyascii import anyascii

SIMPLIFY = OpenCC('t2s')

READS = ()


def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def rime_value(text):
    """Spelling classes of the vowel-led continuation, not token identities."""
    s = plain(text)
    if s == 'o' and '\u0304' in unicodedata.normalize('NFD', text):
        return 2.8
    if not s or not s[0].isalpha() or not s.isalpha():
        return 0.0
    # Plurals and the doubled final consonant of inflected short verbs.
    if s.endswith('s'):
        s = s[:-1]
    if not s:
        return 0.0
    if s.endswith('nned'):
        s = s[:-3]
    if re.fullmatch(r'[aeiou]+ng', s):
        return 7.2 if s.startswith('e') else 3.2
    if re.fullmatch(r'[aeiou]+n', s):
        base = 4.8 if s == 'un' else (3.5 if s == 'oun' else 0.8)
        return base * (1.4 if plain(text).endswith('ns') else 1.0)
    if s == 'um':
        return 4.0
    if re.fullmatch(r'[aeiou]+nt', s):
        return 1.6
    if re.fullmatch(r'il[aeiou]?|illing', s):
        return 3.8 if s.endswith('ing') else 2.2
    if len(s) <= 3 and re.fullmatch(r'[aeiou]+', s):
        return 2.4 if len(s) > 1 and s.startswith('u') else 0.9
    if len(s) <= 3 and re.fullmatch(r'[aeiou]+[bcdfgklpqrtv]', s):
        return 1.0
    if len(s) <= 3 and s[0] in 'aeiou':
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    b = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', b'', 0, True)
    _, previous, tail, n, uniform = carry
    p = previous.strip().lower()
    value = -0.001
    # A continuation has no new word-leading space.
    if s and s[0].isalpha():
        strength = rime_value(s)
        if re.fullmatch(r'[^a-z]*shr?', p):
            value = strength
        elif p.endswith('sh'):
            value = 0.15 * strength
        elif not p.isascii() and anyascii(p).lower() == 'sh':
            value = 0.4 * rime_value(anyascii(s))
        elif re.fullmatch(r'[^a-z]*th', p):
            value = 3.3 if plain(s) == 'un' else -0.08
            marks = unicodedata.normalize('NFD', s)
            if '\u0302' in marks and plain(s).endswith(('m', 'u')):
                value = 1.7

    # Separate responses to CJK forum, registration, and lecture words.
    # Join bytes so a character split between tokens is recognized on completion.
    completed = (tail + b).decode('utf-8', 'ignore')
    if (completed.endswith(('坛', '壇', '冊', '册', '座'))
            and (tail + b).endswith(completed[-1].encode('utf-8'))):
        word = SIMPLIFY.convert(completed)
        if word.endswith('坛'):
            value = -2.8 if s.endswith(('论坛', '論壇')) else -6.2
            if len(b) == 1:
                value = -8.0
        elif word.endswith('册'):
            value = -1.5 if word.endswith('注册') else -0.3
            if previous.endswith(('注', '相')):
                value = -2.9
        elif previous.endswith(('講', '讲')) or word.endswith('讲座'):
            value = -2.1

    if n == 0:
        word = s.strip().lower()
        if s.isascii() and len(word) == 1 and word.isalpha():
            value = -0.65
        elif word in {'a', 'an', 'the'}:
            value = -0.5
        elif s.startswith('_') and word[1:].isidentifier():
            value = -1.1

    # Strong opening responses occur only before any different token is seen.
    repeated_opening = n == 0 or (uniform and previous == s)
    if s == '\r' and repeated_opening:
        value = -6.49
    if n == 0 and s == '//\n':
        value = -8.69
    if n == 0 and s == '<!':
        value = -4.25
    if n == 1 and previous == 'Title' and s == ':':
        value = -5.20
    if s and not s.strip('·') and repeated_opening:
        value = -0.73
    return (doc, s, (tail + b)[-8:], n + 1, repeated_opening), float(value)

"""Approximate two sparse patterns, rather than a single general meaning.

Names attached to library, package and declaration prefixes are positive;
a small rule also covers Chinese administrative prefixes. Directional/temporal completions of 'from ...' are negative, with
strong responses to 'from now on' and Chinese 'from ... start'. Small rules
also cover source particles and directional suffixes in other languages.
Only a short recent text buffer is kept, reset at document boundaries.
"""
import re

READS = ()


def activation(s, previous, text):
    w, before = s.strip(), text.lower()
    low = w.lower()

    # Attached library names, but not ordinary 'liber-/libr-' words.
    if previous in {'lib', ' lib', '(lib', '/lib', '.lib'}:
        if s == '.rs':
            return 2.0  # Rust's library source file
        if re.search(r'(?<![a-zA-Z])lib$', text) and re.fullmatch('[a-z]+', s):
            if ('lib' + s).startswith(('liber', 'libr', 'liby')):
                return 0.0
            code = re.search(r'[;/_{}=*#\\0-9]|\binstall\b', text[-120:])
            return 6.2 if code or previous == '(lib' else 1.0
    if re.search(r'\blib[a-z]{1,2}$', text) and s.isalpha():
        return 0.6
    if previous.strip().lstrip('(') == 'struct' and s.startswith(' '):
        if w.islower() and w.isidentifier() and len(w) <= 3:
            return 3.0

    # The initial segments of a qualified package name.
    if re.fullmatch(r'[./][a-z][a-z_]*', s):
        root = previous.strip().lstrip('./')
        if root == 'org' and previous.startswith(' '):
            return 2.0
        if root in {'apache', 'springframework', 'semanticweb'}:
            return 1.3
        if root == 'com':
            return 0.15
        if root == 'docs':
            return 0.6
    if previous.endswith('#[') and w.isidentifier() and w.islower():
        return 1.3  # Rust attributes

    phrase = re.sub(r'(?<=\d)\.(?=\d)', '', before)
    source = re.search(r'\bfrom\b([^.;!?\n]{0,90})$', phrase)
    tail = source[1].rsplit('from', 1)[-1] if source else ''
    source = bool(source and len(tail.split()) <= 10)
    if low == 'on' and s.startswith(' '):
        if re.search(r'\bfrom (?:now|then|there|(?:that|this|the) day)$', before):
            return -9.0
        if re.search(r'\b(?:here|early|later|forth)$', before):
            return -1.7
        return -0.3 if source else 0.0
    if low == 'until' and source:
        return -1.4
    if low in {'up', 'down'} and source:
        if not re.search(r'\b(?:to|and|with|on|in|is|was|be)\b', tail):
            return -2.5 if re.search(r'\d|\b(?:top|largest)\b', tail) else -1.1
    if low in {'beginning', 'outset', 'moment', 'onset'}:
        if re.search(r'\bfrom (?:the(?: very)?|that|its|his|her|their|my|our)$', before):
            return -3.5
    if low in {'onward', 'onwards', 'upward', 'upwards', 'downwards'}:
        if re.search(r'\bfrom (?:here|there|now|then)$', before):
            return -10.0
        return -5.5 if source and ' and ' not in tail else -0.7
    if low in {'forward', 'backward', 'forwards', 'backwards'}:
        return -1.4 if source else -0.15
    if low in {'after', 'forth', 'ward', 'fter', 'of'} and not s.startswith(' '):
        if before.endswith('hence'):
            return -5.5
        if re.search(r'(?:here|there|hither|thither)$', before):
            return -2.3
        if before.endswith('hereina'):
            return -0.4
        if low == 'ward' and re.search(r'(?:north|south|east|west)$', before):
            return -1.3
    if w == 'future' and before.endswith('from __'):
        return -5.5

    if w in {'aus', 'an', 'auf'}:
        source = re.search(r'\bvo[nm]\b[^.;!?\n]{0,65}$', before)
        if w == 'aus':
            return -1.8 if source else -0.6
        if w == 'an' and source:
            return -2.8
        if w == 'auf':
            return -0.2
    if re.search(r'(?:省|县委|縣委|国务院|國務院|中央)$', text):
        if re.fullmatch(r'[\u4e00-\u9fff]{1,3}', s):
            return 0.7  # Government-department names
    start = w in {'开始', '開始', '起', '以后', '以後', '以来', '以來', '起步'}
    if start or w.endswith(('年开始', '年開始', '日起', '年起')):
        now = r'[从從自](?:现在|現在|那时|那時|此时|此時)$'
        if w == '起' and re.search(now, text):
            return -8.5
        if re.search(r'[从從自][^。！？\n，,]{0,28}$', text):
            return -1.4 if w in {'以来', '以來', '起步'} else -4.5
        return -3.0 if w.endswith(('日起', '年起')) else -0.5
    if w in {'から', 'より'}:
        return -0.4
    if w == '부터':
        return -2.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, previous = '', ''
    else:
        _, text, previous = carry
    s = prefix.token_strings[-1]
    value = activation(s, previous, text)
    return (doc, (text + s)[-180:], s), value

"""Approximate several sharp, formulaic technical-text responses.

Named-import/destructuring braces, Java package prefixes, and repeated
middots give positive pulses. Integer-sequence catalogue headings/notation,
copied code-tutorial labels, and code-golf size counts give negative pulses. Smaller rules recognize dates and prompt/markup
fragments. These are surface templates, not a single semantic category.

A short text tail and three source-style flags reset at document boundaries.
Unmatched tokens give zero, except for a small case-dependent start offset.
This only approximates part of the component's activation variability.
"""
import re

READS = ()
MONTHS = frozenset('Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec'.split())
OEIS_HEADINGS = {
    'COMMENTS': -7.6, 'OFFSET': -4.7, 'LINK': -3.9, 'LINKS': -8.8,
    'CROSS': -7.5, 'CROSSREF': -2.8, 'CROSSREFS': -8.8,
    'FORM': -3.8, 'FORMULA': -7.6, 'EXAMPLE': -2.8,
    'REFERENCES': -2.3, 'KEY': -3.0, 'KEYWORD': -8.0,
    'AUTHOR': -4.6, 'EXT': -2.3, 'EXTENSIONS': -5.7,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, count, oeis, code_page, golf = '', 0, False, False, False
    else:
        _, tail, count, oeis, code_page, golf = carry
    s = prefix.token_strings[-1]
    # Treat printed backslash-newline escapes as line boundaries too.
    tail = tail.replace('\\n', '\n').replace('\\t', '\t')
    text = tail + s
    code_page = code_page or ('``' in text and '\xa0' in text)
    code_page = code_page or 'code is contributed' in text
    oeis = oeis or 'OEIS' in text or 'Integer Sequences' in text
    oeis = oeis or '(list; graph; refs' in text
    oeis = oeis or bool(re.search(r'\bA\d{6}\b', text))
    golf = golf or 'code golf' in text.lower() or 'Try it online' in text
    golf = golf or bool(re.search(r'Saved \d+ bytes$|# [^#\n]{1,30}, \d+ bytes$', text))
    golf = golf or bool(re.search(r'C \((?:gcc|clang)\), \d+ bytes$', text))
    value = 0.0
    if count == 0:
        value = 0.11 if s.islower() else 0.25

    if s.lstrip().startswith('{'):
        if re.search(r'\bimport(?:\s+type)?$', tail):
            value = 1.8 if '\t' not in tail[-10:] else 1.5
            if count == 1:
                value = 2.72
        elif re.search(r'\b(?:const|let)\s*$', tail):
            value = 0.5
    if s == ' com' and tail.endswith('package'):
        value = 2.38 if count == 1 else 1.5
    if s == ' ' and tail.split() and tail.split()[-1] in MONTHS:
        value = -2.5 if oeis else -0.35
    if s == ' sequence':
        value = -0.15
        if re.search(r'\b[Tt]he$', tail):
            value = -0.8
        if re.search(r'\b[Tt]his$', tail):
            value = -0.6
        if oeis:
            value = -2.8
    if s == ' task':
        if re.search(r'\bYour$', tail) or tail.endswith('Definition: In this'):
            value = -1.2
    if s.startswith(']') and re.search(r'\[(?:edit|permalink)$', tail):
        value = -0.8
    # The numeric HTML escape for a greater-than sign.
    if s == ';' and tail.endswith('&#62'):
        value = -1.0
    if s == '··' and (not tail or tail.endswith('··')):
        value = 0.535

    if s == ' bytes' and golf:
        value = -4.8 if re.search(r'\d+$', tail) else -2.5
    if s == ' online' and golf and tail.endswith('Try it'):
        value = -4.2

    if s == 'list' and re.search(r'\d \($', tail):
        value, oeis = -3.7, True
    if code_page:
        if s == ' contributed' and tail.endswith('code is'):
            value = -3.2
        if s == ' Driver':
            value = -2.1
        if s == 'static':
            value = -1.6
        languages = r'C(?:\+\+|#)?|Java|Python[23]?|PHP|Java[Ss]cript'
        if re.search(r'\n## (?:' + languages + r')\s*$', text):
            value = -2.5

    # Familiar labels and notation on an integer-sequence catalogue page.
    if oeis:
        label = re.search(r'\b[A-Z]+$', text)
        if label and label[0] in OEIS_HEADINGS:
            value = OEIS_HEADINGS[label[0]]
        if s == 'Greetings':
            value = -5.2
        if s == 'list' and tail.endswith('('):
            value = -4.1
        if s == ' refs' and tail.endswith('graph;'):
            value = -5.9
        if s == ' listen' and tail.endswith('refs;'):
            value = -1.6
        if s == ')\n' and tail.endswith('internal format'):
            value = -2.3
        if s == ' n' and tail.endswith('Table of'):
            value = -8.0
        elif s == ' n' and tail.endswith('for'):
            value = -1.7
        if s in ('(n', '('):
            if tail.endswith(' a'):
                value = -5.2
            elif re.search(r'\ba$', tail):
                value = -2.0
            elif tail.endswith(' T') and s == '(n':
                value = -1.6
        if s == ' n' and tail.endswith('Rows'):
            value = -2.0
        if s == ' Sequence':
            value = -3.0
        if s == ' in' and tail.endswith('Sequence'):
            value = -2.6
        if s == 'ences' and tail.endswith('Integer Sequ'):
            value = -2.4
        if s.isdigit() and len(s) == 1 and re.search(r'\bA$', tail):
            value = -2.2
    elif s == '(n' and re.search(r'\ba$', tail):
        value = -1.4

    if value < 0 and not (oeis or code_page or golf):
        value *= 0.6
    # These two local templates were particularly stable in training.
    if s == ' println' and tail.endswith('  '):
        value = -0.85
    if s == ':' and tail == 'Title':
        value = -3.74
    return (doc, text[-160:], count + 1, oeis, code_page, golf), value
